import React from 'react';

export const INITIAL_BALANCE = 21;

export const VIP_LEVELS = [
  { level: 1, expNeeded: 0, label: 'Bronze' },
  { level: 2, expNeeded: 10000, label: 'Silver' },
  { level: 3, expNeeded: 50000, label: 'Gold' },
  { level: 4, expNeeded: 200000, label: 'Platinum' },
  { level: 5, expNeeded: 500000, label: 'Diamond' },
  { level: 6, expNeeded: 1000000, label: 'Master' },
  { level: 7, expNeeded: 5000000, label: 'Elite' },
  { level: 8, expNeeded: 10000000, label: 'Legend' },
  { level: 9, expNeeded: 50000000, label: 'Mythic' },
  { level: 10, expNeeded: 100000000, label: 'Immortal' },
];

export const COLOR_CONFIG = {
  RED: { bg: 'bg-red-600', shadow: 'shadow-red-500/50', label: 'Red' },
  GREEN: { bg: 'bg-green-600', shadow: 'shadow-green-500/50', label: 'Green' },
  VIOLET: { bg: 'bg-purple-600', shadow: 'shadow-purple-500/50', label: 'Violet' }
};

export const COLORS_BY_NUMBER: Record<number, string[]> = {
  0: ['RED', 'VIOLET'], 1: ['GREEN'], 2: ['RED'], 3: ['GREEN'], 4: ['RED'],
  5: ['GREEN', 'VIOLET'], 6: ['RED'], 7: ['GREEN'], 8: ['RED'], 9: ['GREEN']
};

import React, { useState, useMemo } from 'react';
import { UserState, Tab } from '../types.ts';
import { VIP_LEVELS } from '../constants.tsx';
import AIGenerationView from './AIGenerationView.tsx';

interface ProfileViewProps { 
  user: UserState; 
  setTab: (tab: Tab) => void; 
  onUpdateUser: (updatedUser: UserState) => void;
  onRedeemGiftCode: (code: string) => void; 
}

const ProfileView: React.FC<ProfileViewProps> = ({ user, setTab, onUpdateUser, onRedeemGiftCode }) => {
  const [showAIGen, setShowAIGen] = useState(false);
  const [showGiftCodeInput, setShowGiftCodeInput] = useState(false);
  const [giftCode, setGiftCode] = useState('');

  const vipInfo = useMemo(() => {
    const currentVip = VIP_LEVELS.find(v => v.level === user.vipLevel) || VIP_LEVELS[0];
    const nextVip = VIP_LEVELS.find(v => v.level === user.vipLevel + 1);
    if (!nextVip) return { currentVip, nextVip: null, progress: 100, needed: 0 };
    const range = nextVip.expNeeded - currentVip.expNeeded;
    const currentVal = Math.max(0, user.totalTurnover - currentVip.expNeeded);
    const progress = Math.min(100, (currentVal / range) * 100);
    const needed = nextVip.expNeeded - user.totalTurnover;
    return { currentVip, nextVip, progress, needed };
  }, [user.vipLevel, user.totalTurnover]);

  const handleShare = () => {
    const shareText = `🚀 Join RITIK CLUB! Play the best color prediction and mini-games. Use my referral code: ${user.referralCode} to get 🪙 21 Rupya bonus! 💎`;
    if (navigator.share) {
      navigator.share({
        title: 'Ritik Club Official',
        text: shareText,
        url: window.location.href,
      }).catch(console.error);
    } else {
      navigator.clipboard.writeText(shareText);
      alert("Referral link and code copied to clipboard! Share it with your friends.");
    }
  };

  if (showAIGen) {
    return (
      <div className="p-4 animate-in fade-in duration-500">
        <div className="flex items-center gap-4 mb-6">
          <button onClick={() => setShowAIGen(false)} className="text-2xl w-10 h-10 flex items-center justify-center bg-white/5 rounded-full">❮</button>
          <h2 className="text-xl font-bold font-orbitron">AI Avatar Forge</h2>
        </div>
        <AIGenerationView onAvatarCreated={(url) => { onUpdateUser({ ...user, avatarUrl: url }); setShowAIGen(false); }} />
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 px-4 pt-8 animate-in fade-in duration-500">
      {/* Profile Header */}
      <div className="flex flex-col items-center">
        <div className="relative">
          <div className="absolute -inset-2 bg-gradient-to-tr from-blue-600 to-purple-600 rounded-full blur-lg opacity-40 animate-pulse"></div>
          {user.avatarUrl ? (
            <img src={user.avatarUrl} alt="Avatar" className="relative w-28 h-28 rounded-full object-cover border-4 border-[#11131a] shadow-2xl" />
          ) : (
            <div className="relative w-28 h-28 rounded-full bg-gradient-to-tr from-[#1e2330] to-[#11131a] flex items-center justify-center text-5xl border-4 border-[#11131a] shadow-2xl">👤</div>
          )}
          <button onClick={() => setShowAIGen(true)} className="absolute bottom-0 right-0 w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center border-4 border-[#11131a] shadow-lg active:scale-90">✨</button>
        </div>
        <h2 className="mt-6 text-2xl font-black font-orbitron tracking-tight">{user.phone}</h2>
        <div className="mt-1 px-3 py-1 bg-blue-500/10 rounded-full border border-blue-500/20">
           <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest">ID: {user.id}</span>
        </div>
      </div>

      {/* Referral Program Card */}
      <div className="bg-gradient-to-br from-indigo-900 via-blue-900 to-[#1e2330] rounded-[2.5rem] p-8 border border-white/10 shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-4 text-5xl opacity-10 group-hover:scale-125 transition-transform duration-700">📣</div>
        <div className="relative z-10">
          <h3 className="text-xl font-black font-orbitron text-white mb-2">REFER & EARN</h3>
          <p className="text-[10px] text-blue-200 font-bold uppercase tracking-widest mb-6">Claim 5% commission on friends play</p>

          <div className="flex items-center gap-4 mb-8">
            <div className="flex-1 bg-black/40 rounded-2xl p-4 border border-white/5">
              <p className="text-[8px] text-gray-500 uppercase font-black mb-1">My Invite Code</p>
              <p className="text-lg font-black font-mono text-white tracking-widest">{user.referralCode}</p>
            </div>
            <button onClick={handleShare} className="w-14 h-14 bg-white text-blue-900 rounded-2xl flex items-center justify-center text-2xl shadow-xl active:scale-90 transition-all">📤</button>
          </div>

          <div className="grid grid-cols-2 gap-4">
             <div className="text-center bg-white/5 rounded-2xl py-3 border border-white/5">
                <p className="text-[8px] text-gray-500 font-black uppercase">Total Invited</p>
                <p className="text-lg font-black font-orbitron">12</p>
             </div>
             <div className="text-center bg-white/5 rounded-2xl py-3 border border-white/5">
                <p className="text-[8px] text-gray-500 font-black uppercase">Earned</p>
                <p className="text-lg font-black font-orbitron text-green-400">🪙 1.2k</p>
             </div>
          </div>
        </div>
      </div>

      {/* VIP & Experience */}
      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 shadow-lg space-y-4">
        <div className="flex justify-between items-center">
           <h3 className="text-sm font-black font-orbitron text-yellow-500 uppercase tracking-widest">VIP Level: {vipInfo.currentVip.label}</h3>
           <span className="text-[9px] font-black text-gray-500">EXP: {user.totalTurnover.toLocaleString()}</span>
        </div>
        <div className="h-5 w-full bg-black/40 rounded-full overflow-hidden border border-white/5 p-1 relative">
           <div className="h-full bg-gradient-to-r from-yellow-600 via-amber-400 to-yellow-500 rounded-full shadow-[0_0_15px_rgba(234,179,8,0.5)] transition-all duration-1000" style={{ width: `${vipInfo.progress}%` }}></div>
           <div className="absolute inset-0 flex items-center justify-center">
              <span className="text-[8px] font-black text-white mix-blend-difference">{vipInfo.progress.toFixed(0)}% to {vipInfo.nextVip?.label || 'MAX'}</span>
           </div>
        </div>
      </div>

      {/* Navigation Options */}
      <div className="bg-[#1e2330] rounded-[2.5rem] overflow-hidden divide-y divide-white/5 border border-white/5">
        <button onClick={() => setTab(Tab.WALLET)} className="w-full p-6 flex justify-between items-center text-xs font-black uppercase group active:bg-white/5">
          <span className="flex items-center gap-4">💰 <span className="text-gray-400 group-hover:text-white transition-colors tracking-widest">Withdrawal & Deposit</span></span>
          <span className="text-gray-600 group-hover:translate-x-1 transition-transform">❯</span>
        </button>
        <button onClick={() => setShowGiftCodeInput(!showGiftCodeInput)} className="w-full p-6 flex justify-between items-center text-xs font-black uppercase group active:bg-white/5">
          <span className="flex items-center gap-4">🧧 <span className="text-gray-400 group-hover:text-white transition-colors tracking-widest">Gift Code Redeem</span></span>
          <span className={`text-gray-600 transition-transform ${showGiftCodeInput ? 'rotate-90' : ''}`}>❯</span>
        </button>
        {showGiftCodeInput && (
          <div className="bg-black/40 p-6 animate-in slide-in-from-top duration-300 space-y-4">
             <input 
               type="text" 
               value={giftCode} 
               onChange={(e) => setGiftCode(e.target.value.toUpperCase())} 
               placeholder="PASTE CODE HERE" 
               className="w-full bg-[#11131a] border border-white/10 rounded-2xl py-4 px-6 text-sm font-black text-white uppercase text-center focus:ring-1 focus:ring-blue-500 outline-none" 
             />
             <button onClick={() => { if(giftCode) onRedeemGiftCode(giftCode); setGiftCode(''); }} className="w-full bg-blue-600 py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-lg shadow-blue-900/20 active:scale-95 transition-all">Apply Code</button>
          </div>
        )}
      </div>

      {/* Logout */}
      <button 
        onClick={() => { localStorage.clear(); window.location.reload(); }} 
        className="w-full py-6 bg-red-600/10 text-red-500 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border border-red-500/20 active:scale-95 transition-all"
      >
        Exit App Session
      </button>

      <div className="text-center space-y-1 opacity-40">
        <p className="text-[8px] text-gray-500 font-black uppercase tracking-widest">Ritik Club Official Network</p>
        <p className="text-[7px] text-gray-600 font-bold">Ver 2.8.5 Stable • Global Server</p>
      </div>
    </div>
  );
};

export default ProfileView;

import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameType, GameMode, Transaction, UserBet, GameResult, ColorType, BigSmallType } from './types.ts';
import { INITIAL_BALANCE, COLORS_BY_NUMBER } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import AuthModal from './components/AuthModal.tsx';
import AdminView from './views/AdminView.tsx';
import LeaderboardView from './views/LeaderboardView.tsx';
import WinGoGame from './views/WinGoGame.tsx';
import AviatorGame from './views/AviatorGame.tsx';
import MinesGame from './views/MinesGame.tsx';
import ChickenRoad2 from './views/ChickenRoad2.tsx';
import VortexGame from './views/VortexGame.tsx';
import CricketGame from './views/CricketGame.tsx';
import K3Game from './views/K3Game.tsx';
import D5Game from './views/D5Game.tsx';
import TRXGame from './views/TRXGame.tsx';
import DragonTigerGame from './views/DragonTigerGame.tsx';
import PlinkoGame from './views/PlinkoGame.tsx';
import AviaMasterGame from './views/AviaMasterGame.tsx';
import ReferralView from './views/ReferralView.tsx';
import ResultModal from './components/ResultModal.tsx';

const ADMIN_PHONE = "6207559408";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeGame, setActiveGame] = useState<GameType | null>(null);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');

  const [winGoTimeLeft, setWinGoTimeLeft] = useState(30);
  const [winGoPeriod, setWinGoPeriod] = useState("");
  const [winGoResults, setWinGoResults] = useState<GameResult[]>(() => {
    const saved = localStorage.getItem('ritik_club_wingo_res');
    return saved ? JSON.parse(saved) : [];
  });

  const [showResultModal, setShowResultModal] = useState(false);
  const [modalResult, setModalResult] = useState<GameResult | null>(null);
  const [modalProfit, setModalProfit] = useState(0);

  const [overrideWinGoNumber, setOverrideWinGoNumber] = useState<number | null>(null);

  const [dbUsers, setDbUsers] = useState<UserState[]>(() => {
    const saved = localStorage.getItem('ritik_club_v2_db');
    return saved ? JSON.parse(saved) : [];
  });

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('ritik_club_v2_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('ritik_club_v2_tx');
    return saved ? JSON.parse(saved) : [];
  });

  const [allBets, setAllBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('ritik_club_v2_bets');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      const seconds = now.getSeconds();
      const cycle = 30;
      const remaining = cycle - (seconds % cycle);
      setWinGoTimeLeft(remaining);

      const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
      const totalSecondsInDay = (now.getHours() * 3600) + (now.getMinutes() * 60) + seconds;
      const periodSeq = Math.floor(totalSecondsInDay / cycle).toString().padStart(4, '0');
      const currentPeriod = dateStr + periodSeq;

      if (currentPeriod !== winGoPeriod) {
        if (winGoPeriod !== "") {
          processWinGoResult(winGoPeriod);
        }
        setWinGoPeriod(currentPeriod);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [winGoPeriod]);

  const processWinGoResult = useCallback((periodToProcess: string) => {
    let winningNum = overrideWinGoNumber !== null ? overrideWinGoNumber : Math.floor(Math.random() * 10);
    setOverrideWinGoNumber(null); 

    const colors = COLORS_BY_NUMBER[winningNum] as ColorType[];
    const bigSmall: BigSmallType = winningNum >= 5 ? 'Big' : 'Small';

    const newResult: GameResult = {
      id: "RES" + Date.now(),
      period: periodToProcess,
      number: winningNum,
      colors,
      bigSmall,
      timestamp: Date.now()
    };

    setWinGoResults(prev => {
      const updated = [newResult, ...prev].slice(0, 50);
      localStorage.setItem('ritik_club_wingo_res', JSON.stringify(updated));
      return updated;
    });

    let currentTurnProfit = 0;
    let hasParticipated = false;

    setAllBets(prev => {
      const updatedBets = prev.map(bet => {
        if (bet.game === GameType.WINGO && bet.period === periodToProcess && bet.status === 'Pending') {
          hasParticipated = true;
          let isWin = false;
          let payout = 0;

          if (typeof bet.selection === 'number') {
            isWin = bet.selection === winningNum;
            payout = isWin ? bet.amount * 9 : 0;
          } else if (Object.values(ColorType).includes(bet.selection)) {
            isWin = colors.includes(bet.selection);
            if (isWin) {
              if (bet.selection === ColorType.VIOLET) payout = bet.amount * 4.5;
              else if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) payout = bet.amount * 1.5;
              else payout = bet.amount * 2;
            }
          } else if (bet.selection === 'Big' || bet.selection === 'Small') {
            isWin = bet.selection === bigSmall;
            payout = isWin ? bet.amount * 1.98 : 0;
          }

          if (isWin) currentTurnProfit += payout;
          return { ...bet, status: isWin ? 'Win' : 'Loss', payout };
        }
        return bet;
      });

      // Show modal logic
      if (hasParticipated) {
        setModalResult(newResult);
        setModalProfit(currentTurnProfit);
        setShowResultModal(true);

        if (currentTurnProfit > 0 && user) {
           updateUser({ ...user, balance: user.balance + currentTurnProfit });
        }
      }

      return updatedBets;
    });
  }, [user, overrideWinGoNumber]);

  useEffect(() => {
    localStorage.setItem('ritik_club_v2_db', JSON.stringify(dbUsers));
    localStorage.setItem('ritik_club_v2_session', JSON.stringify(user));
    localStorage.setItem('ritik_club_v2_tx', JSON.stringify(transactions));
    localStorage.setItem('ritik_club_v2_bets', JSON.stringify(allBets));
  }, [dbUsers, user, transactions, allBets]);

  const handleAuth = (phone: string, password: string, isRegistering: boolean, referralCode?: string) => {
    if (isRegistering) {
      const alreadyExists = dbUsers.some(u => u.phone === phone);
      if (alreadyExists) {
        alert("यह नंबर पहले से रजिस्टर है! लॉगिन करें।");
        return;
      }
      const newUser: UserState = {
        id: "U" + Math.floor(100000 + Math.random() * 900000),
        phone,
        password,
        balance: INITIAL_BALANCE,
        referralCode: referralCode || "RC" + Math.floor(1000 + Math.random() * 9000),
        vipLevel: 1,
        totalTurnover: 0,
        hasDeposited: false
      };
      setDbUsers(prev => [...prev, newUser]);
      setUser(newUser);
    } else {
      const found = dbUsers.find(u => u.phone === phone && u.password === password);
      if (!found) {
        alert("गलत नंबर या पासवर्ड!");
        return;
      }
      setUser(found);
    }
  };

  const updateUser = (updated: UserState) => {
    setUser(updated);
    setDbUsers(prev => prev.map(u => u.id === updated.id ? updated : u));
  };

  const handleBet = (betData: any) => {
    if (!user || user.balance < betData.amount) {
      alert("Insufficient balance!");
      return null;
    }
    const newBet: UserBet = {
      id: "B" + Math.floor(100000 + Math.random() * 900000),
      game: betData.game || GameType.WINGO,
      period: betData.period || (betData.game === GameType.WINGO ? winGoPeriod : "LATEST"),
      mode: activeMode,
      amount: betData.amount,
      selection: betData.selection,
      status: 'Pending',
      timestamp: Date.now()
    };
    setAllBets(prev => [newBet, ...prev]);
    updateUser({ ...user, balance: user.balance - betData.amount, totalTurnover: user.totalTurnover + betData.amount });
    return newBet.id;
  };

  const handleWin = (betId: string, payout: number) => {
    setAllBets(prev => prev.map(b => b.id === betId ? { ...b, status: payout > 0 ? 'Win' : 'Loss', payout } : b));
    if (user && payout > 0) {
      updateUser({ ...user, balance: user.balance + payout });
    }
  };

  const renderGame = () => {
    if (!user) return null;
    switch (activeGame) {
      case GameType.WINGO:
        return <WinGoGame onBack={() => setActiveGame(null)} balance={user.balance} activeMode={activeMode} setActiveMode={setActiveMode} period={winGoPeriod} timeLeft={winGoTimeLeft} results={winGoResults} onBet={handleBet} userBets={allBets.filter(b => b.game === GameType.WINGO)} lastProfit={modalProfit} triggerWinLossAnimation={false} onWinLossAnimationComplete={() => {}} overrideNumber={overrideWinGoNumber} />;
      case GameType.AVIATOR:
        return <AviatorGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.AVIATOR)} overrideCrashPoint={null} onSetOverrideCrashPoint={() => {}} />;
      case GameType.AVIA_MASTER:
        return <AviaMasterGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.AVIA_MASTER)} />;
      case GameType.MINES:
        return <MinesGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.MINES)} generateMinesLayout={(p, count) => [1, 5, 10, 15, 20].slice(0, count)} />;
      case GameType.CHICKEN_ROAD_2:
        return <ChickenRoad2 onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.CHICKEN_ROAD_2)} />;
      case GameType.VORTEX:
        return <VortexGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.VORTEX)} overrideResult={null} onSetOverrideResult={() => {}} />;
      case GameType.CRICKET:
        return <CricketGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.CRICKET)} overrideNextRun={null} onSetOverrideNextRun={() => {}} />;
      case GameType.K3:
        return <K3Game onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.K3)} overrideK3Dice={null} onSetOverrideK3Dice={() => {}} />;
      case GameType.D5:
        return <D5Game onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.D5)} override5DDigits={null} onSetOverride5DDigits={() => {}} />;
      case GameType.TRX:
        return <TRXGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.TRX)} overrideTRXDigit={null} onSetOverrideTRXDigit={() => {}} />;
      case GameType.DRAGON_TIGER:
        return <DragonTigerGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.DRAGON_TIGER)} overrideDTResult={null} onSetOverrideDTResult={() => {}} />;
      case GameType.PLINKO:
        return <PlinkoGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.PLINKO)} overridePlinkoIndex={null} onSetOverridePlinkoIndex={() => {}} />;
      default: return null;
    }
  };

  if (!user) return <AuthModal onLogin={handleAuth} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center selection:bg-blue-500/30">
      <div className="w-full max-w-md pb-20 relative h-screen overflow-y-auto no-scrollbar shadow-2xl bg-[#11131a]">
        {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={setActiveGame} notice="Ritik Club Official: Join the best simulation arena! Withdrawals processed within 10 minutes." />}
        {activeTab === Tab.HOME && activeGame && renderGame()}
        {activeTab === Tab.LEADERBOARD && <LeaderboardView members={dbUsers.map(u => ({ id: u.id, phone: u.phone, totalTurnover: u.totalTurnover }))} currentUser={user} />}
