}

const AdminSection: React.FC<AdminSectionProps> = ({ id, icon, title, color, expandedId, onToggle, children }) => {
  const isExpanded = expandedId === id;
  return (
    <div className="bg-[#1e2330] rounded-[2rem] overflow-hidden border border-white/5 shadow-xl">
      <button onClick={() => onToggle(id)} className="w-full p-6 flex justify-between items-center text-xs font-black uppercase group active:bg-white/5">
        <span className="flex items-center gap-3">{icon} <span className={`${color} group-hover:text-white transition-colors`}>{title}</span></span>
        <span className={`text-gray-600 transition-transform ${isExpanded ? 'rotate-90' : ''}`}>❯</span>
      </button>
      {isExpanded && (
        <div className="bg-black/40 p-6 animate-in slide-in-from-top duration-300 space-y-4">
          {children}
        </div>
      )}
