  );
};

interface AdminViewProps {
  tdsPool: number;
  onRewardUser: (userId: string, amount: number) => void;
  leaderboardMembers: Array<{ id: string; phone: string; totalTurnover: number }>;
  overrideWinGoNumber: number | null;
  onSetWinGoNumberOverride: (num: number | null) => void;
  overrideAviatorCrash: number | null;
  onSetAviatorCrashOverride: (point: number | null) => void;
  aviatorPeriodData: { period: string; deterministicCrash: string };
  overrideCricketRun: number | null;
  onSetCricketRunOverride: (run: number | null) => void;
  cricketPeriodData: { period: string; deterministicRun: number };
  overrideVortexResult: number | null;
  onSetVortexResultOverride: (result: number | null) => void;
  vortexPeriodData: { period: string; deterministicResult: number };
  overrideK3Dice: number[] | null;
  onSetK3DiceOverride: (dice: number[] | null) => void;
  override5DDigits: number[] | null;
  onSet5DDigitsOverride: (digits: number[] | null) => void;
  overrideTRXDigit: number | null;
  onSetTRXDigitOverride: (digit: number | null) => void;
  overrideDTResult: string | null;
  onSetDTResultOverride: (result: string | null) => void;
  overridePlinkoIndex: number | null;
  onSetPlinkoIndexOverride: (index: number | null) => void;
  minesLayoutGenerator: (period: string, mineCount: number) => number[];
  chickenObstaclesGenerator: (period: string) => number[];
  pendingWithdrawalRequests: Transaction[];
  onProcessWithdrawal: (transactionId: string, status: TransactionStatus, message?: string) => void;
  pendingDepositRequests: Transaction[];
  onProcessDeposit: (transactionId: string, status: TransactionStatus, message?: string) => void;
  allUsers: Array<{ id: string; phone: string }>;
  onCreateGiftCode: (code: string, coins: number) => void;
  onDeleteGiftCode: (code: string) => void;
  availableGiftCodes: GiftCode[];
  userBets: UserBet[]; 
  onUpdateNotice: (text: string) => void;
  currentNotice: string;
}

const AdminView: React.FC<AdminViewProps> = (props) => {
  const { 
    tdsPool, overrideWinGoNumber, onSetWinGoNumberOverride, onSetAviatorCrashOverride,
    pendingDepositRequests, onProcessDeposit, pendingWithdrawalRequests, onProcessWithdrawal,
    onUpdateNotice, currentNotice, allUsers
  } = props;

  const [currentSeed, setCurrentSeed] = useState("");
  const [expandedSection, setExpandedSection] = useState<string | null>(null);
  const [noticeInput, setNoticeInput] = useState(currentNotice);
  const [selectedScreenshot, setSelectedScreenshot] = useState<string | null>(null);
