      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 space-y-4 shadow-2xl">
        <h3 className="font-black font-orbitron text-xs text-orange-400 uppercase tracking-widest">Withdrawals ({pendingWithdrawalRequests.length})</h3>
