              <p className="text-[10px] font-mono text-blue-400">{req.upiId}</p>
              <div className="flex gap-2">
                <button onClick={() => onProcessWithdrawal(req.id, 'Completed')} className="flex-1 bg-blue-600 py-2 rounded-lg text-[9px] font-black uppercase">Approve</button>
                <button onClick={() => onProcessWithdrawal(req.id, 'Rejected')} className="flex-1 bg-red-600/20 py-2 rounded-lg text-[9px] font-black uppercase text-red-500">Decline</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 space-y-4 shadow-2xl">
        <h3 className="font-black font-orbitron text-xs text-green-400 uppercase tracking-widest">Deposits ({pendingDepositRequests.length})</h3>
        <div className="space-y-4 max-h-[300px] overflow-y-auto no-scrollbar">
          {pendingDepositRequests.map(req => (
            <div key={req.id} className="bg-[#11131a] p-4 rounded-3xl border border-white/5 space-y-3">
              <p className="text-xs font-black">{getUserPhoneById(req.userId)} - <span className="text-green-500">₹{req.amount}</span></p>
              <p className="text-[9px] font-mono text-gray-500">UTR: {req.utr}</p>
              {req.screenshotUrl && <img src={req.screenshotUrl} onClick={() => setSelectedScreenshot(req.screenshotUrl || null)} className="w-full h-20 object-cover rounded-lg cursor-pointer" alt="Proof" />}
              <div className="flex gap-2">
                <button onClick={() => onProcessDeposit(req.id, 'Completed')} className="flex-1 bg-green-600 py-2 rounded-lg text-[9px] font-black uppercase">Approve</button>
                <button onClick={() => onProcessDeposit(req.id, 'Rejected')} className="flex-1 bg-red-600/20 py-2 rounded-lg text-[9px] font-black uppercase text-red-500">Decline</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {selectedScreenshot && (
        <div className="fixed inset-0 z-[200] bg-black/95 flex items-center justify-center p-4">
           <div className="w-full max-w-md bg-white rounded-3xl overflow-hidden p-2 relative">
              <img src={selectedScreenshot} alt="Full View" className="w-full h-auto rounded-2xl" />
              <button onClick={() => setSelectedScreenshot(null)} className="absolute top-4 right-4 w-10 h-10 bg-black/50 text-white rounded-full flex items-center justify-center">✕</button>
           </div>
        </div>
      )}
    </div>
  );
};

export default AdminView;

