    const saved = localStorage.getItem('ritik_club_wingo_res');
    return saved ? JSON.parse(saved) : [];
  });

  const [showResultModal, setShowResultModal] = useState(false);
  const [modalResult, setModalResult] = useState<GameResult | null>(null);
