  const [customGameLinks, setCustomGameLinks] = useState<{name: string, url: string}[]>(() => {
    const saved = localStorage.getItem('ritik_club_game_links');
    return saved ? JSON.parse(saved) : [];
  });

  // Overrides Ref for Timer Logic
  const [overrideWinGoNumber, setOverrideWinGoNumber] = useState<number | null>(null);
  const [overrideAviatorCrash, setOverrideAviatorCrash] = useState<number | null>(null);
  const [overrideTRXDigit, setOverrideTRXDigit] = useState<number | null>(null);
  const [overrideDTResult, setOverrideDTResult] = useState<string | null>(null);
  const [overridePlinkoIndex, setOverridePlinkoIndex] = useState<number | null>(null);
  const [overrideK3Dice, setOverrideK3Dice] = useState<number[] | null>(null);
  const [override5DDigits, setOverride5DDigits] = useState<number[] | null>(null);
  const [overrideVortexResult, setOverrideVortexResult] = useState<number | null>(null);
  const [overrideCricketRun, setOverrideCricketRun] = useState<number | null>(null);

  const overridesRef = useRef({
    wingo: overrideWinGoNumber,
    aviator: overrideAviatorCrash,
    trx: overrideTRXDigit,
    dt: overrideDTResult,
    plinko: overridePlinkoIndex,
    k3: overrideK3Dice,
    d5: override5DDigits,
    vortex: overrideVortexResult,
    cricket: overrideCricketRun
  });

  useEffect(() => {
    overridesRef.current = {
      wingo: overrideWinGoNumber,
      aviator: overrideAviatorCrash,
      trx: overrideTRXDigit,
      dt: overrideDTResult,
      plinko: overridePlinkoIndex,
      k3: overrideK3Dice,
      d5: override5DDigits,
      vortex: overrideVortexResult,
      cricket: overrideCricketRun
    };
  }, [overrideWinGoNumber, overrideAviatorCrash, overrideTRXDigit, overrideDTResult, overridePlinkoIndex, overrideK3Dice, override5DDigits, overrideVortexResult, overrideCricketRun]);

  const [dbUsers, setDbUsers] = useState<UserState[]>(() => {
    const saved = localStorage.getItem('ritik_club_v2_db');
    return saved ? JSON.parse(saved) : [];
  });

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('ritik_club_v2_session');
    return saved ? JSON.parse(saved) : null;
  });

  const userRef = useRef<UserState | null>(null);
  useEffect(() => { userRef.current = user; }, [user]);

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('ritik_club_v2_tx');
    return saved ? JSON.parse(saved) : [];
  });

  const [allBets, setAllBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('ritik_club_v2_bets');
    return saved ? JSON.parse(saved) : [];
  });
  const betsRef = useRef<UserBet[]>([]);
  useEffect(() => { betsRef.current = allBets; }, [allBets]);

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      const seconds = now.getSeconds();
      const cycle = 30;
      const remaining = cycle - (seconds % cycle);
      setWinGoTimeLeft(remaining);

      const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
      const totalSecondsInDay = (now.getHours() * 3600) + (now.getMinutes() * 60) + seconds;
      const periodSeq = Math.floor(totalSecondsInDay / cycle).toString().padStart(4, '0');
      const currentPeriod = dateStr + periodSeq;

      setWinGoPeriod(prev => {
        if (prev !== "" && currentPeriod !== prev) {
          processWinGoResult(prev);
        }
        return currentPeriod;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const processWinGoResult = (periodToProcess: string) => {
    const currentBets = betsRef.current.filter(b => b.game === GameType.WINGO && b.period === periodToProcess && b.status === 'Pending');

    let winningNum = overridesRef.current.wingo;

    // SMART HOUSE LOGIC: If no admin override, pick the outcome with the LOWEST payout
    if (winningNum === null) {
      let lowestPayout = Infinity;
      let bestNumber = 0;

      for (let n = 0; n <= 9; n++) {
        let potentialPayout = 0;
        const colors = COLORS_BY_NUMBER[n] as ColorType[];
        const bs: BigSmallType = n >= 5 ? 'Big' : 'Small';

        currentBets.forEach(bet => {
          if (typeof bet.selection === 'number' && bet.selection === n) {
            potentialPayout += bet.amount * 8.92;
          } else if (Object.values(ColorType).includes(bet.selection) && colors.includes(bet.selection)) {
             if (bet.selection === ColorType.VIOLET) potentialPayout += bet.amount * 4.41;
             else if ((n === 0 || n === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) potentialPayout += bet.amount * 1.5;
             else potentialPayout += bet.amount * 1.96;
          } else if ((bet.selection === 'Big' || bet.selection === 'Small') && bet.selection === bs) {
            potentialPayout += bet.amount * 1.96;
          }
        });

        if (potentialPayout < lowestPayout) {
          lowestPayout = potentialPayout;
          bestNumber = n;
        }
      }
      winningNum = bestNumber;
    }

    setOverrideWinGoNumber(null);
    const resColors = COLORS_BY_NUMBER[winningNum] as ColorType[];
    const resBS: BigSmallType = winningNum >= 5 ? 'Big' : 'Small';

    const newResult: GameResult = {
      id: "RES" + Date.now(), period: periodToProcess, number: winningNum,
      colors: resColors, bigSmall: resBS, timestamp: Date.now()
    };

    setWinGoResults(prev => {
      const updated = [newResult, ...prev].slice(0, 50);
      localStorage.setItem('ritik_club_wingo_res', JSON.stringify(updated));
      return updated;
    });

    let currentTurnProfit = 0;
    let hasParticipated = false;

    const updatedBetsList = betsRef.current.map(bet => {
      if (bet.game === GameType.WINGO && bet.period === periodToProcess && bet.status === 'Pending') {
        hasParticipated = true;
        let isWin = false;
        let payout = 0;

        if (typeof bet.selection === 'number') {
          isWin = bet.selection === winningNum;
          payout = isWin ? bet.amount * 8.92 : 0;
        } else if (Object.values(ColorType).includes(bet.selection)) {
          isWin = resColors.includes(bet.selection);
          if (isWin) {
            if (bet.selection === ColorType.VIOLET) payout = bet.amount * 4.41;
            else if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) payout = bet.amount * 1.5;
            else payout = bet.amount * 1.96;
          }
        } else if (bet.selection === 'Big' || bet.selection === 'Small') {
          isWin = bet.selection === resBS;
          payout = isWin ? bet.amount * 1.96 : 0;
        }

        if (isWin) currentTurnProfit += payout;
        return { ...bet, status: isWin ? 'Win' : 'Loss', payout };
      }
      return bet;
    });

    setAllBets(updatedBetsList);

    if (hasParticipated) {
      setModalResult(newResult);
      setModalProfit(currentTurnProfit);
      setShowResultModal(true);
      if (currentTurnProfit > 0 && userRef.current) {
         updateUser({ ...userRef.current, balance: userRef.current.balance + currentTurnProfit });
      }
    }
  };

  useEffect(() => {
    localStorage.setItem('ritik_club_v2_db', JSON.stringify(dbUsers));
    localStorage.setItem('ritik_club_v2_session', JSON.stringify(user));
    localStorage.setItem('ritik_club_v2_tx', JSON.stringify(transactions));
    localStorage.setItem('ritik_club_v2_bets', JSON.stringify(allBets));
    localStorage.setItem('ritik_club_gift_codes', JSON.stringify(giftCodes));
    localStorage.setItem('ritik_club_game_links', JSON.stringify(customGameLinks));
  }, [dbUsers, user, transactions, allBets, giftCodes, customGameLinks]);

  const handleAuth = (phone: string, password: string, isRegistering: boolean, referralCode?: string) => {
    if (isRegistering) {
      const alreadyExists = dbUsers.some(u => u.phone === phone);
      if (alreadyExists) return alert("Number already registered!");
      const newUser: UserState = {
        id: "U" + Math.floor(100000 + Math.random() * 900000),
        phone, password, balance: INITIAL_BALANCE,
        referralCode: referralCode || "RC" + Math.floor(1000 + Math.random() * 9000),
        vipLevel: 1, totalTurnover: 0, hasDeposited: false
      };
      setDbUsers(prev => [...prev, newUser]);
      setUser(newUser);
    } else {
      const found = dbUsers.find(u => u.phone === phone && u.password === password);
      if (!found) return alert("Invalid credentials!");
      setUser(found);
    }
  };

  const updateUser = (updated: UserState) => {
    setUser(updated);
    setDbUsers(prev => prev.map(u => u.id === updated.id ? updated : u));
  };

  const handleBet = (betData: any) => {
    if (!user || user.balance < betData.amount) {
      alert("Insufficient balance!");
      return null;
    }
    const newBet: UserBet = {
      id: "B" + Math.floor(100000 + Math.random() * 900000),
      game: betData.game || GameType.WINGO,
      period: betData.period || (betData.game === GameType.WINGO ? winGoPeriod : "LATEST"),
      mode: activeMode,
      amount: betData.amount,
      selection: betData.selection,
      status: 'Pending',
      timestamp: Date.now()
    };
    const updatedBets = [newBet, ...allBets];
    setAllBets(updatedBets);
    betsRef.current = updatedBets;
    updateUser({ ...user, balance: user.balance - betData.amount, totalTurnover: user.totalTurnover + betData.amount });
    return newBet.id;
  };

  const handleWin = (betId: string, payout: number) => {
    setAllBets(prev => prev.map(b => b.id === betId ? { ...b, status: payout > 0 ? 'Win' : 'Loss', payout } : b));
    if (userRef.current && payout > 0) {
      updateUser({ ...userRef.current, balance: userRef.current.balance + payout });
    }
  };

  const handleRedeemGift = (code: string) => {
    const gc = giftCodes.find(g => g.code === code);
    if (!gc) return alert("Invalid gift code!");
    if (!user) return;
    updateUser({ ...user, balance: user.balance + gc.coins });
    setGiftCodes(prev => prev.filter(g => g.code !== code));
    alert(`Success! Redeemed 🪙 ${gc.coins}`);
  };

  // Critical fix: Return early if no user is found to prevent property access of null
  if (!user) {
    return <AuthModal onLogin={handleAuth} />;
  }

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center selection:bg-blue-500/30">
      <div className="w-full max-w-md pb-20 relative h-screen overflow-y-auto no-scrollbar shadow-2xl bg-[#11131a]">
        {activeTab === Tab.HOME && !activeGame && (
          <HomeView user={user} onSelectGame={setActiveGame} customLinks={customGameLinks} notice="Ritik Club Official: Smart House Protocol Active." />
        )}
        {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame onBack={() => setActiveGame(null)} balance={user.balance} activeMode={activeMode} setActiveMode={setActiveMode} period={winGoPeriod} timeLeft={winGoTimeLeft} results={winGoResults} onBet={handleBet} userBets={allBets.filter(b => b.game === GameType.WINGO)} lastProfit={modalProfit} triggerWinLossAnimation={false} onWinLossAnimationComplete={() => {}} overrideNumber={overrideWinGoNumber} />}
        {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.AVIATOR)} overrideCrashPoint={overrideAviatorCrash} onSetOverrideCrashPoint={setOverrideAviatorCrash} />}
        {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.MINES)} generateMinesLayout={(p, count) => [1, 5, 10, 15, 20].slice(0, count)} />}
        {activeTab === Tab.HOME && activeGame === GameType.VORTEX && <VortexGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.VORTEX)} overrideResult={overrideVortexResult} onSetOverrideResult={setOverrideVortexResult} />}
        {activeTab === Tab.HOME && activeGame === GameType.CRICKET && <CricketGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.CRICKET)} overrideNextRun={overrideCricketRun} onSetOverrideNextRun={setOverrideCricketRun} />}
        {activeTab === Tab.HOME && activeGame === GameType.K3 && <K3Game onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.K3)} overrideK3Dice={overrideK3Dice} onSetOverrideK3Dice={setOverrideK3Dice} />}
        {activeTab === Tab.HOME && activeGame === GameType.D5 && <D5Game onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.D5)} override5DDigits={override5DDigits} onSetOverride5DDigits={setOverride5DDigits} />}
        {activeTab === Tab.HOME && activeGame === GameType.TRX && <TRXGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.TRX)} overrideTRXDigit={overrideTRXDigit} onSetOverrideTRXDigit={setOverrideTRXDigit} />}
        {activeTab === Tab.HOME && activeGame === GameType.DRAGON_TIGER && <DragonTigerGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.DRAGON_TIGER)} overrideDTResult={overrideDTResult} onSetOverrideDTResult={setOverrideDTResult} />}
        {activeTab === Tab.HOME && activeGame === GameType.PLINKO && <PlinkoGame onBack={() => setActiveGame(null)} balance={user.balance} onBet={handleBet} onWin={handleWin} userBets={allBets.filter(b => b.game === GameType.PLINKO)} overridePlinkoIndex={overridePlinkoIndex} onSetOverridePlinkoIndex={setOverridePlinkoIndex} />}

        {activeTab === Tab.LEADERBOARD && <LeaderboardView members={dbUsers.map(u => ({ id: u.id, phone: u.phone, totalTurnover: u.totalTurnover }))} currentUser={user} />}
        {activeTab === Tab.HISTORY && <ReferralView user={user} />}
        {activeTab === Tab.WALLET && (
          <WalletView 
            balance={user.balance} hasDeposited={user.hasDeposited} 
            onDeposit={(utr, amt, upi, ss) => {
              const tx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Deposit', amount: amt, coins: amt*10, status: 'Pending', timestamp: Date.now(), utr, userUpiId: upi, screenshotUrl: ss };
              setTransactions(prev => [tx, ...prev]);
              alert("Wait for admin approval!");
            }} 
            onWithdrawalRequest={(coins, upi, tds) => {
              const tx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Withdrawal', coins, status: 'Pending', timestamp: Date.now(), upiId: upi, tdsAmount: tds };
              setTransactions(prev => [tx, ...prev]);
              updateUser({ ...user, balance: user.balance - coins });
            }} 
            transactions={transactions.filter(t => t.userId === user.id)} 
          />
        )}
        {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} onUpdateUser={updateUser} onRedeemGiftCode={handleRedeemGift} />}

        {activeTab === Tab.ADMIN && user.phone === ADMIN_PHONE && (
          <AdminView 
            tdsPool={0} allUsers={dbUsers} userBets={allBets.filter(b => b.period === winGoPeriod)}
            pendingDepositRequests={transactions.filter(t => t.type === 'Deposit' && t.status === 'Pending')}
            pendingWithdrawalRequests={transactions.filter(t => t.type === 'Withdrawal' && t.status === 'Pending')}
            onProcessDeposit={(id, status) => {
              const tx = transactions.find(t => t.id === id);
              if (tx && status === 'Completed') {
                const u = dbUsers.find(usr => usr.id === tx.userId);
                if (u) updateUser({ ...u, balance: u.balance + tx.coins, hasDeposited: true });
              }
              setTransactions(prev => prev.map(t => t.id === id ? { ...t, status } : t));
            }}
            onProcessWithdrawal={(id, status) => setTransactions(prev => prev.map(t => t.id === id ? { ...t, status } : t))}
            onUpdateNotice={() => {}} currentNotice="Ritik Club Official" 
            onSetWinGoNumberOverride={setOverrideWinGoNumber} overrideWinGoNumber={overrideWinGoNumber}
            onSetAviatorCrashOverride={setOverrideAviatorCrash} overrideAviatorCrash={overrideAviatorCrash}
            onSetTRXDigitOverride={setOverrideTRXDigit} overrideTRXDigit={overrideTRXDigit}
            onSetDTResultOverride={setOverrideDTResult} overrideDTResult={overrideDTResult}
            onSetPlinkoIndexOverride={setOverridePlinkoIndex} overridePlinkoIndex={overridePlinkoIndex}
            onSetK3DiceOverride={setOverrideK3Dice} overrideK3Dice={overrideK3Dice}
            onSet5DDigitsOverride={setOverride5DDigits} override5DDigits={override5DDigits}
            onSetVortexResultOverride={setOverrideVortexResult} overrideVortexResult={overrideVortexResult}
            onSetCricketRunOverride={setOverrideCricketRun} overrideCricketRun={overrideCricketRun}
            onCreateGiftCode={(code, coins) => setGiftCodes(prev => [...prev, {code, coins}])}
            onDeleteGiftCode={(code) => setGiftCodes(prev => prev.filter(g => g.code !== code))}
            availableGiftCodes={giftCodes}
            onAddGameLink={(name, url) => setCustomGameLinks(prev => [...prev, {name, url}])}
            onDeleteGameLink={(url) => setCustomGameLinks(prev => prev.filter(l => l.url !== url))}
            customGameLinks={customGameLinks}
          />
        )}
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} />
        <ResultModal result={modalResult} userProfit={modalProfit} hasBet={showResultModal} onClose={() => setShowResultModal(false)} />
      </div>
    </div>
  );
};

export default App;

