        <p className="text-[10px] font-black text-white/50 uppercase tracking-[0.3em] relative z-10">High Fidelity Simulation</p>
        <div className="mt-4 flex items-center gap-2 relative z-10">
           <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_#22c55e]"></span>
           <span className="text-[9px] font-black text-green-400 uppercase tracking-widest">Global Protocol Active</span>
        </div>
      </div>

      {/* Global Notice Marquee */}
      <div className="bg-[#1e2330] py-2 px-4 rounded-2xl flex items-center gap-3 border border-white/5 shadow-inner overflow-hidden">
        <div className="flex-shrink-0 w-8 h-8 bg-blue-500/10 rounded-lg flex items-center justify-center text-blue-400">🔔</div>
        <div className="flex-1 overflow-hidden">
           <div className="whitespace-nowrap animate-[marquee_20s_linear_infinite] text-[10px] font-bold text-gray-300 uppercase tracking-widest">
             {notice} • Welcome {user.phone} • Join the official group for daily bonuses • Withdrawals processed within 10 minutes • 
           </div>
        </div>
      </div>

      {/* Custom Admin Game Links */}
      {customLinks.length > 0 && (
        <div className="space-y-2">
           <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest ml-1">Featured External Arenas</p>
           <div className="flex gap-2 overflow-x-auto no-scrollbar">
              {customLinks.map((link, idx) => (
                <a 
                  key={idx} 
                  href={link.url} 
                  target="_blank" 
                  className="bg-gradient-to-br from-indigo-600 to-purple-700 px-6 py-3 rounded-2xl text-[10px] font-black uppercase border border-white/10 shadow-lg whitespace-nowrap active:scale-95 transition-all"
                >
                  🚀 {link.name}
                </a>
              ))}
           </div>
        </div>
      )}

      {/* Categories Navigator */}
      <div className="sticky top-0 z-40 -mx-4 px-4 py-2 bg-[#11131a]/95 backdrop-blur-md border-b border-white/5">
        <div className="flex gap-3 overflow-x-auto no-scrollbar">
          {categories.map((c, i) => (
