              onClick={() => setActiveCategory(c)}
              className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest whitespace-nowrap border transition-all ${activeCategory === c ? 'bg-blue-600 border-blue-400 shadow-lg text-white' : 'bg-white/5 border-white/5 text-gray-500'}`}
