           />
           <button 
             onClick={() => { onRedeemGiftCode(giftInput); setGiftInput(''); }}
             className="bg-green-600 px-6 rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-green-900/20 active:scale-95 transition-all"
           >
             Redeem
           </button>
        </div>
      </div>

      <div className="bg-gradient-to-br from-indigo-900 via-blue-900 to-[#1e2330] rounded-[2.5rem] p-8 border border-white/10 shadow-2xl relative overflow-hidden group">
        <div className="relative z-10">
          <h3 className="text-xl font-black font-orbitron text-white mb-2">REFER & EARN</h3>
          <p className="text-[10px] text-blue-200 font-bold uppercase tracking-widest mb-6">Earn on friends play</p>
          <div className="flex items-center gap-4 mb-2">
            <div className="flex-1 bg-black/40 rounded-2xl p-4 border border-white/5">
