          if (bet.selection === ColorType.VIOLET) mult = 4.41;
        }
        if (win) { profit += (bet.amount * mult); return { ...bet, status: 'Win', payout: bet.amount * mult }; }
        return { ...bet, status: 'Loss', payout: 0 };
      }
      return bet;
    }));

    if (profit > 0) {
      setUser(curr => {
        if (!curr) return null;
        const updated = { ...curr, balance: curr.balance + profit };
        setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
        return updated;
      });
    }

    if (activeGame === GameType.WINGO && mode === activeMode && hadBet) {
      setLastResult(result); setLastProfit(profit); setIsResultModalOpen(true);
    }
  }, [activeGame, activeMode, userBets, adminOverrides, user]);

  useEffect(() => {
    const interval = setInterval(() => {
      (Object.keys(MODE_DURATIONS) as GameMode[]).forEach(mode => {
        const { periodId } = getSyncData(mode);
        if (lastProcessedPeriod[mode] && lastProcessedPeriod[mode] !== periodId) processDraw(mode, lastProcessedPeriod[mode]);
        setLastProcessedPeriod(prev => ({ ...prev, [mode]: periodId }));
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lastProcessedPeriod, processDraw]);

  const handleAuth = (phone: string, password: string, isRegistering: boolean, referralCode?: string) => {
    if (isRegistering) {
      const existing = dbUsers.find(u => u.phone === phone);
      if (existing) return alert("Phone number already registered. Please Login.");
      const newUser: UserState = {
        id: "U" + Date.now().toString().slice(-6),
        phone,
        password,
        balance: WELCOME_BONUS,
        referralCode: referralCode || "RC" + Math.floor(1000 + Math.random() * 8999),
        vipLevel: 1,
        totalTurnover: 0
      };
      setDbUsers(prev => [...prev, newUser]);
      setUser(newUser);
    } else {
      const userFound = dbUsers.find(u => u.phone === phone && u.password === password);
      if (userFound) {
        setUser(userFound);
      } else {
        alert("Invalid phone or password!");
      }
    }
  };

  const handleBet = (bet: any) => {
    const { periodId } = getSyncData(activeMode);
    const newBet: UserBet = { ...bet, mode: activeMode, period: periodId, id: "BT" + Math.random().toString(36).substr(2, 5).toUpperCase(), timestamp: Date.now(), status: 'Pending' };
    setUserBets(prev => [newBet, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance - bet.amount, totalTurnover: curr.totalTurnover + bet.amount };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
  };

  const handleDeposit = (data: { utr: string, upiId: string, screenshot: string, amount: number }) => {
    // 1 Rupee = 10 Coins
    const coinsCalculated = data.amount * 10;
    const newTx: Transaction = { 
      id: "TX" + Date.now(), 
      userId: user!.id, 
      type: 'Deposit', 
      amount: data.amount, // INR Amount
      coins: coinsCalculated, // Coins Amount
      status: 'Pending', 
      timestamp: Date.now(), 
      utr: data.utr, 
      userUpiId: data.upiId, 
      screenshotUrl: data.screenshot 
    };
    setTransactions(prev => [newTx, ...prev]);
    alert(`Deposit of ₹${data.amount} (will credit ${coinsCalculated} coins) submitted!`);
  };

  const handleWithdrawal = (data: { amount: number, upiId: string }) => {
    if (user!.balance < data.amount) return alert("Insufficient balance!");
    const newTx: Transaction = { id: "TX" + Date.now(), userId: user!.id, type: 'Withdrawal', amount: data.amount, coins: data.amount, status: 'Pending', timestamp: Date.now(), userUpiId: data.upiId };
    setTransactions(prev => [newTx, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance - data.amount };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
    alert("Withdrawal submitted!");
  };

  const handleProcessTx = (id: string, status: 'Completed' | 'Rejected') => {
    setTransactions(prev => prev.map(tx => {
      if (tx.id === id) {
        if (tx.status !== 'Pending') return tx; // Only process pending

        // If Deposit Approved -> Add Balance to that specific User
        if (tx.type === 'Deposit' && status === 'Completed') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              // If this user is the one currently logged in, update session too
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }

        // If Withdrawal Rejected -> Refund Balance to that specific User
        if (tx.type === 'Withdrawal' && status === 'Rejected') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }

        return { ...tx, status };
      }
      return tx;
    }));
  };

  const sync = getSyncData(activeMode);

  if (!user) return <AuthModal onAuth={handleAuth} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a] shadow-2xl overflow-x-hidden">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={true} onClose={() => setIsResultModalOpen(false)} />}
        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-md px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            {activeGame && <button onClick={() => setActiveGame(null)} className="mr-2 text-xl">❮</button>}
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center font-black">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron tracking-tighter">Ritik Club</h1>
              <p className="text-[8px] font-black text-green-500 uppercase tracking-widest">Global Protocol Active</p>
            </div>
          </div>
          <div className="text-right">
             <p className="text-[10px] text-gray-500 font-black">BALANCE</p>
             <p className="text-sm font-black text-yellow-500 font-orbitron">🪙 {user.balance.toFixed(2)}</p>
          </div>
        </header>

        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={setActiveGame} customGames={customGames} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode]} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame balance={user.balance} onUpdateBalance={(v) => setUser(u => {
             if(!u) return null;
             const updated = {...u, balance: u.balance + v};
             setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
             return updated;
          })} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame balance={user.balance} onUpdateBalance={(v) => setUser(u => {
             if(!u) return null;
             const updated = {...u, balance: u.balance + v};
             setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
             return updated;
          })} />}
          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} onUpdateUser={setUser} onRedeemGift={(code) => {
             const g = giftCodes.find(x => x.code === code);
             if (g) { 
               setUser(u => {
                 if(!u) return null;
                 const updated = {...u, balance: u.balance + g.amount};
                 setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
                 return updated;
               });
               setGiftCodes(prev => prev.filter(x => x.code !== code)); alert("Redeemed!"); 
             }
          }} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={transactions.filter(t => t.userId === user.id)} onDeposit={handleDeposit} onWithdraw={handleWithdrawal} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode]} userBets={userBets} />}
          {activeTab === Tab.ADMIN && user.phone === ADMIN_PHONE && (
            <AdminView 
              overrides={adminOverrides as any} onSetOverride={(m, n) => setAdminOverrides(prev => ({ ...prev, [m]: n }))} 
              giftCodes={giftCodes} onAddGift={(g) => setGiftCodes(p => [...p, g])} onAddGame={(g) => setCustomGames(p => [...p, g])} onRemoveGame={(id) => setCustomGames(p => p.filter(x => x.id !== id))} customGames={customGames}
              pendingTxs={transactions.filter(t => t.status === 'Pending')} onProcessTx={handleProcessTx}
            />
          )}
        </main>
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} />
      </div>
    </div>
  );
};

