import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Tab, UserState, GameResult, ColorType, BigSmallType, UserBet, GameMode, GameType, GiftCode, CustomGame, Transaction, Message } from './types.ts';
import { COLORS_BY_NUMBER } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import AdminView from './views/AdminView.tsx';
import InboxView from './views/InboxView.tsx';
import AuthModal from './components/AuthModal.tsx';
import ResultModal from './components/ResultModal.tsx';
import WinGoGame from './views/WinGoGame.tsx';
import AviatorGame from './views/AviatorGame.tsx';
import MinesGame from './views/MinesGame.tsx';

const ADMIN_PHONE = "6207559408";
const WELCOME_BONUS = 25;
const MODE_DURATIONS: Record<GameMode, number> = { '30sec': 30, '1min': 60, '3min': 180, '5min': 300 };

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeGame, setActiveGame] = useState<GameType | null>(null);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');

  const [dbUsers, setDbUsers] = useState<UserState[]>(() => {
    const saved = localStorage.getItem('rc_users_db');
    return saved ? JSON.parse(saved) : [];
  });

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('rc_current_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [userBets, setUserBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('rc_bets');
    return saved ? JSON.parse(saved) : [];
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('rc_tx');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('rc_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [giftCodes, setGiftCodes] = useState<GiftCode[]>(() => {
    const saved = localStorage.getItem('rc_gifts');
    return saved ? JSON.parse(saved) : [];
  });

  const [customGames, setCustomGames] = useState<CustomGame[]>(() => {
    const saved = localStorage.getItem('rc_custom_games');
    return saved ? JSON.parse(saved) : [];
  });

  const [adminOverrides, setAdminOverrides] = useState<Record<string, any>>({});
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [lastProcessedPeriod, setLastProcessedPeriod] = useState<Record<string, string>>({});
  const [lastResult, setLastResult] = useState<GameResult | null>(null);
  const [lastProfit, setLastProfit] = useState<number>(0);
  const [results, setResults] = useState<Record<string, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });

  // Sync state with LocalStorage
  useEffect(() => {
    localStorage.setItem('rc_users_db', JSON.stringify(dbUsers));
    if (user) {
      localStorage.setItem('rc_current_session', JSON.stringify(user));
    } else {
      localStorage.removeItem('rc_current_session');
    }
  }, [user, dbUsers]);

  useEffect(() => {
    localStorage.setItem('rc_bets', JSON.stringify(userBets));
    localStorage.setItem('rc_tx', JSON.stringify(transactions));
    localStorage.setItem('rc_messages', JSON.stringify(messages));
    localStorage.setItem('rc_gifts', JSON.stringify(giftCodes));
    localStorage.setItem('rc_custom_games', JSON.stringify(customGames));
  }, [userBets, transactions, messages, giftCodes, customGames]);

  const getSyncData = (mode: GameMode) => {
    const now = Date.now();
    const duration = MODE_DURATIONS[mode];
    const periodTimestamp = Math.floor(now / (duration * 1000));
    const timeLeft = duration - (Math.floor(now / 1000) % duration);
    const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    return { periodId: `${dateStr}${mode}${periodTimestamp}`, timeLeft };
  };

  const processDraw = useCallback((mode: GameMode, period: string) => {
    const currentBets = userBets.filter(b => b.mode === mode && b.period === period && b.status === 'Pending');
    let winningNum: number;

    if (adminOverrides[mode] !== undefined && adminOverrides[mode] !== null) {
      winningNum = adminOverrides[mode];
      setAdminOverrides(prev => ({ ...prev, [mode]: null }));
    } else {
      let minPayout = Infinity;
      let bestNumber = 0;
      for (let n = 0; n <= 9; n++) {
        let totalHousePayout = 0;
        const colors = COLORS_BY_NUMBER[n] as ColorType[];
        const bs = n >= 5 ? 'Big' : 'Small';
        currentBets.forEach(bet => {
          if (typeof bet.selection === 'number' && bet.selection === n) totalHousePayout += bet.amount * 8.92;
          else if (bet.selection === 'Big' || bet.selection === 'Small') {
            if (bet.selection === bs) totalHousePayout += bet.amount * 1.96;
          } else if (colors.includes(bet.selection as ColorType)) {
            let mult = 1.96;
            if ((n === 0 || n === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
            if (bet.selection === ColorType.VIOLET) mult = 4.41;
            totalHousePayout += bet.amount * mult;
          }
        });
        if (totalHousePayout < minPayout) { minPayout = totalHousePayout; bestNumber = n; }
      }
      winningNum = bestNumber;
    }

    const result: GameResult = {
      id: "RES" + Math.random().toString(36).substr(2, 5).toUpperCase(),
      period,
      number: winningNum,
      colors: COLORS_BY_NUMBER[winningNum] as ColorType[],
      bigSmall: winningNum >= 5 ? 'Big' : 'Small',
      timestamp: Date.now()
    };

    setResults(prev => ({ ...prev, [mode]: [result, ...prev[mode]].slice(0, 50) }));

    let profit = 0;
    let hadBet = false;
    setUserBets(prev => prev.map(bet => {
      if (bet.mode === mode && bet.period === period && bet.status === 'Pending') {
        hadBet = true;
        let win = false;
        let mult = 0;
        if (typeof bet.selection === 'number') { if (bet.selection === winningNum) { win = true; mult = 8.92; } }
        else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.96; } }
        else if (result.colors.includes(bet.selection as ColorType)) {
          win = true; mult = 1.96;
          if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
          if (bet.selection === ColorType.VIOLET) mult = 4.41;
        }
        if (win) { profit += (bet.amount * mult); return { ...bet, status: 'Win', payout: bet.amount * mult }; }
        return { ...bet, status: 'Loss', payout: 0 };
      }
      return bet;
    }));

    if (profit > 0) {
      setUser(curr => {
        if (!curr) return null;
        const updated = { ...curr, balance: curr.balance + profit };
        setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
        return updated;
      });
    }

    if (activeGame === GameType.WINGO && mode === activeMode && hadBet) {
      setLastResult(result); setLastProfit(profit); setIsResultModalOpen(true);
    }
  }, [activeGame, activeMode, userBets, adminOverrides, user]);

  useEffect(() => {
    const interval = setInterval(() => {
      (Object.keys(MODE_DURATIONS) as GameMode[]).forEach(mode => {
        const { periodId } = getSyncData(mode);
        if (lastProcessedPeriod[mode] && lastProcessedPeriod[mode] !== periodId) processDraw(mode, lastProcessedPeriod[mode]);
        setLastProcessedPeriod(prev => ({ ...prev, [mode]: periodId }));
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lastProcessedPeriod, processDraw]);

  const handleAuth = (phone: string, password: string, isRegistering: boolean, referralCode?: string) => {
    if (isRegistering) {
      const existing = dbUsers.find(u => u.phone === phone);
      if (existing) return alert("Phone number already registered. Please Login.");
      const newUser: UserState = {
        id: "U" + Date.now().toString().slice(-6),
        phone,
        password,
        balance: WELCOME_BONUS,
        referralCode: referralCode || "RC" + Math.floor(1000 + Math.random() * 8999),
        vipLevel: 1,
        totalTurnover: 0
      };
      setDbUsers(prev => [...prev, newUser]);
      setUser(newUser);
    } else {
      const userFound = dbUsers.find(u => u.phone === phone && u.password === password);
      if (userFound) {
        setUser(userFound);
      } else {
        alert("Invalid phone or password!");
      }
    }
  };

  const handleBet = (bet: any) => {
    const { periodId } = getSyncData(activeMode);
    const newBet: UserBet = { ...bet, mode: activeMode, period: periodId, id: "BT" + Math.random().toString(36).substr(2, 5).toUpperCase(), timestamp: Date.now(), status: 'Pending' };
    setUserBets(prev => [newBet, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance - bet.amount, totalTurnover: curr.totalTurnover + bet.amount };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
  };

  const handleDeposit = (data: { utr: string, upiId: string, screenshot: string, amount: number }) => {
    const coinsCalculated = data.amount * 10;
    const newTx: Transaction = { 
      id: "TX" + Date.now(), 
      userId: user!.id, 
      type: 'Deposit', 
      amount: data.amount,
      coins: coinsCalculated,
      status: 'Pending', 
      timestamp: Date.now(), 
      utr: data.utr, 
      userUpiId: data.upiId, 
      screenshotUrl: data.screenshot 
    };
    setTransactions(prev => [newTx, ...prev]);
    alert(`Deposit of ₹${data.amount} submitted!`);
  };

  const handleWithdrawal = (data: { amount: number, upiId: string }) => {
    if (user!.balance < data.amount) return alert("Insufficient balance!");
    const newTx: Transaction = { id: "TX" + Date.now(), userId: user!.id, type: 'Withdrawal', amount: data.amount, coins: data.amount, status: 'Pending', timestamp: Date.now(), userUpiId: data.upiId };
    setTransactions(prev => [newTx, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance - data.amount };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
    alert("Withdrawal submitted!");
  };

  const handleProcessTx = (id: string, status: 'Completed' | 'Rejected', adminMessage?: string) => {
    setTransactions(prev => prev.map(tx => {
      if (tx.id === id) {
        if (tx.status !== 'Pending') return tx;

        // Balance handling logic
        if (tx.type === 'Deposit' && status === 'Completed') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }

        if (tx.type === 'Withdrawal' && status === 'Rejected') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }

        // Send Inbox Message if provided or standard
        const title = tx.type === 'Withdrawal' 
          ? `Withdrawal ${status}` 
          : `Deposit ${status}`;

        const defaultContent = status === 'Completed' 
          ? `Your ${tx.type.toLowerCase()} of ₹${tx.amount} has been approved.` 
          : `Your ${tx.type.toLowerCase()} of ₹${tx.amount} has been rejected.`;

        const content = adminMessage ? `${defaultContent}\n\nNote from Admin: ${adminMessage}` : defaultContent;

        const newMsg: Message = {
          id: "MSG" + Date.now(),
          userId: tx.userId,
          title,
          content,
          timestamp: Date.now(),
          isRead: false,
          type: 'Wallet'
        };
        setMessages(prevMsgs => [newMsg, ...prevMsgs]);

        return { ...tx, status };
      }
      return tx;
    }));
  };

  const handleMarkRead = (id: string) => {
    setMessages(prev => prev.map(m => m.id === id ? { ...m, isRead: true } : m));
  };

  const handleClearInbox = () => {
    if (user) {
      setMessages(prev => prev.filter(m => m.userId !== user.id));
    }
  };

  const sync = getSyncData(activeMode);
  const unreadCount = user ? messages.filter(m => m.userId === user.id && !m.isRead).length : 0;

  if (!user) return <AuthModal onAuth={handleAuth} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a] shadow-2xl overflow-x-hidden">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={true} onClose={() => setIsResultModalOpen(false)} />}
        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-md px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            {activeGame && <button onClick={() => setActiveGame(null)} className="mr-2 text-xl">❮</button>}
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center font-black">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron tracking-tighter">Ritik Club</h1>
              <p className="text-[8px] font-black text-green-500 uppercase tracking-widest">Global Protocol Active</p>
            </div>
          </div>
          <div className="text-right">
             <p className="text-[10px] text-gray-500 font-black">BALANCE</p>
             <p className="text-sm font-black text-yellow-500 font-orbitron">🪙 {user.balance.toFixed(2)}</p>
          </div>
        </header>

        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={setActiveGame} customGames={customGames} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode]} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame balance={user.balance} onUpdateBalance={(v) => setUser(u => {
             if(!u) return null;
             const updated = {...u, balance: u.balance + v};
             setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
             return updated;
          })} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame balance={user.balance} onUpdateBalance={(v) => setUser(u => {
             if(!u) return null;
             const updated = {...u, balance: u.balance + v};
             setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
             return updated;
          })} />}
          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} onUpdateUser={setUser} onRedeemGift={(code) => {
             const g = giftCodes.find(x => x.code === code);
             if (g) { 
               setUser(u => {
                 if(!u) return null;
                 const updated = {...u, balance: u.balance + g.amount};
                 setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
                 return updated;
               });
               setGiftCodes(prev => prev.filter(x => x.code !== code)); alert("Redeemed!"); 
             }
          }} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={transactions.filter(t => t.userId === user.id)} onDeposit={handleDeposit} onWithdraw={handleWithdrawal} />}
          {activeTab === Tab.INBOX && <InboxView messages={messages.filter(m => m.userId === user.id)} onMarkRead={handleMarkRead} onClearAll={handleClearInbox} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode]} userBets={userBets} />}
          {activeTab === Tab.ADMIN && user.phone === ADMIN_PHONE && (
            <AdminView 
              overrides={adminOverrides as any} onSetOverride={(m, n) => setAdminOverrides(prev => ({ ...prev, [m]: n }))} 
              giftCodes={giftCodes} onAddGift={(g) => setGiftCodes(p => [...p, g])} onAddGame={(g) => setCustomGames(p => [...p, g])} onRemoveGame={(id) => setCustomGames(p => p.filter(x => x.id !== id))} customGames={customGames}
              pendingTxs={transactions.filter(t => t.status === 'Pending')} onProcessTx={handleProcessTx}
            />
          )}
        </main>
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} unreadCount={unreadCount} />
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Tab, UserState, GameResult, ColorType, BigSmallType, UserBet, GameMode, GameType, GiftCode, CustomGame, Transaction, Message } from './types.ts';
import { COLORS_BY_NUMBER } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import AdminView from './views/AdminView.tsx';
import InboxView from './views/InboxView.tsx';
import AuthModal from './components/AuthModal.tsx';
import ResultModal from './components/ResultModal.tsx';
import WinGoGame from './views/WinGoGame.tsx';
import AviatorGame from './views/AviatorGame.tsx';
import MinesGame from './views/MinesGame.tsx';

const ADMIN_PHONE = "6207559408";
const WELCOME_BONUS = 25;
const MODE_DURATIONS: Record<GameMode, number> = { '30sec': 30, '1min': 60, '3min': 180, '5min': 300 };

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeGame, setActiveGame] = useState<GameType | null>(null);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');

  const [dbUsers, setDbUsers] = useState<UserState[]>(() => {
    const saved = localStorage.getItem('rc_users_db');
    return saved ? JSON.parse(saved) : [];
  });

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('rc_current_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [userBets, setUserBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('rc_bets');
    return saved ? JSON.parse(saved) : [];
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('rc_tx');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('rc_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [giftCodes, setGiftCodes] = useState<GiftCode[]>(() => {
    const saved = localStorage.getItem('rc_gifts');
    return saved ? JSON.parse(saved) : [];
  });

  const [customGames, setCustomGames] = useState<CustomGame[]>(() => {
    const saved = localStorage.getItem('rc_custom_games');
    return saved ? JSON.parse(saved) : [];
  });

  const [adminOverrides, setAdminOverrides] = useState<Record<string, any>>({});
  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [lastProcessedPeriod, setLastProcessedPeriod] = useState<Record<string, string>>({});
  const [lastResult, setLastResult] = useState<GameResult | null>(null);
  const [lastProfit, setLastProfit] = useState<number>(0);
  const [results, setResults] = useState<Record<string, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });

  // Sync state with LocalStorage
  useEffect(() => {
    localStorage.setItem('rc_users_db', JSON.stringify(dbUsers));
    if (user) {
      localStorage.setItem('rc_current_session', JSON.stringify(user));
    } else {
      localStorage.removeItem('rc_current_session');
    }
  }, [user, dbUsers]);

  useEffect(() => {
    localStorage.setItem('rc_bets', JSON.stringify(userBets));
    localStorage.setItem('rc_tx', JSON.stringify(transactions));
    localStorage.setItem('rc_messages', JSON.stringify(messages));
    localStorage.setItem('rc_gifts', JSON.stringify(giftCodes));
    localStorage.setItem('rc_custom_games', JSON.stringify(customGames));
  }, [userBets, transactions, messages, giftCodes, customGames]);

  const getSyncData = (mode: GameMode) => {
    const now = Date.now();
    const duration = MODE_DURATIONS[mode];
    const periodTimestamp = Math.floor(now / (duration * 1000));
    const timeLeft = duration - (Math.floor(now / 1000) % duration);
    const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    return { periodId: `${dateStr}${mode}${periodTimestamp}`, timeLeft };
  };

  const processDraw = useCallback((mode: GameMode, period: string) => {
    const currentBets = userBets.filter(b => b.mode === mode && b.period === period && b.status === 'Pending');
    let winningNum: number;

    if (adminOverrides[mode] !== undefined && adminOverrides[mode] !== null) {
      winningNum = adminOverrides[mode];
      setAdminOverrides(prev => ({ ...prev, [mode]: null }));
    } else {
      let minPayout = Infinity;
      let bestNumber = 0;
      for (let n = 0; n <= 9; n++) {
        let totalHousePayout = 0;
        const colors = COLORS_BY_NUMBER[n] as ColorType[];
        const bs = n >= 5 ? 'Big' : 'Small';
        currentBets.forEach(bet => {
          if (typeof bet.selection === 'number' && bet.selection === n) totalHousePayout += bet.amount * 8.92;
          else if (bet.selection === 'Big' || bet.selection === 'Small') {
            if (bet.selection === bs) totalHousePayout += bet.amount * 1.96;
          } else if (colors.includes(bet.selection as ColorType)) {
            let mult = 1.96;
            if ((n === 0 || n === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
            if (bet.selection === ColorType.VIOLET) mult = 4.41;
            totalHousePayout += bet.amount * mult;
          }
        });
        if (totalHousePayout < minPayout) { minPayout = totalHousePayout; bestNumber = n; }
      }
      winningNum = bestNumber;
    }

    const result: GameResult = {
      id: "RES" + Math.random().toString(36).substr(2, 5).toUpperCase(),
      period,
      number: winningNum,
      colors: COLORS_BY_NUMBER[winningNum] as ColorType[],
      bigSmall: winningNum >= 5 ? 'Big' : 'Small',
      timestamp: Date.now()
    };

    setResults(prev => ({ ...prev, [mode]: [result, ...prev[mode]].slice(0, 50) }));

    let profit = 0;
    let hadBet = false;
    setUserBets(prev => prev.map(bet => {
      if (bet.mode === mode && bet.period === period && bet.status === 'Pending') {
        hadBet = true;
        let win = false;
        let mult = 0;
        if (typeof bet.selection === 'number') { if (bet.selection === winningNum) { win = true; mult = 8.92; } }
        else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.96; } }
        else if (result.colors.includes(bet.selection as ColorType)) {
          win = true; mult = 1.96;
          if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
          if (bet.selection === ColorType.VIOLET) mult = 4.41;
        }
        if (win) { profit += (bet.amount * mult); return { ...bet, status: 'Win', payout: bet.amount * mult }; }
        return { ...bet, status: 'Loss', payout: 0 };
      }
      return bet;
    }));

    if (profit > 0) {
      setUser(curr => {
        if (!curr) return null;
        const updated = { ...curr, balance: curr.balance + profit };
        setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
        return updated;
      });
    }

    if (activeGame === GameType.WINGO && mode === activeMode && hadBet) {
      setLastResult(result); setLastProfit(profit); setIsResultModalOpen(true);
    }
  }, [activeGame, activeMode, userBets, adminOverrides, user]);

  useEffect(() => {
    const interval = setInterval(() => {
      (Object.keys(MODE_DURATIONS) as GameMode[]).forEach(mode => {
        const { periodId } = getSyncData(mode);
        if (lastProcessedPeriod[mode] && lastProcessedPeriod[mode] !== periodId) processDraw(mode, lastProcessedPeriod[mode]);
        setLastProcessedPeriod(prev => ({ ...prev, [mode]: periodId }));
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lastProcessedPeriod, processDraw]);

  const handleAuth = (phone: string, password: string, isRegistering: boolean, referralCode?: string) => {
    if (isRegistering) {
      const existing = dbUsers.find(u => u.phone === phone);
      if (existing) return alert("Phone number already registered. Please Login.");
      const newUser: UserState = {
        id: "U" + Date.now().toString().slice(-6),
        phone,
        password,
        balance: WELCOME_BONUS,
        referralCode: referralCode || "RC" + Math.floor(1000 + Math.random() * 8999),
        vipLevel: 1,
        totalTurnover: 0
      };
      setDbUsers(prev => [...prev, newUser]);
      setUser(newUser);
    } else {
      const userFound = dbUsers.find(u => u.phone === phone && u.password === password);
      if (userFound) {
        setUser(userFound);
      } else {
        alert("Invalid phone or password!");
      }
    }
  };

  const handleBet = (bet: any) => {
    const { periodId } = getSyncData(activeMode);
    const newBet: UserBet = { ...bet, mode: activeMode, period: periodId, id: "BT" + Math.random().toString(36).substr(2, 5).toUpperCase(), timestamp: Date.now(), status: 'Pending' };
    setUserBets(prev => [newBet, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance - bet.amount, totalTurnover: curr.totalTurnover + bet.amount };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
  };

  const handleDeposit = (data: { utr: string, upiId: string, screenshot: string, amount: number }) => {
    if (data.amount < 20) return alert("Minimum deposit is ₹20");
    const coinsCalculated = data.amount * 10;
    const newTx: Transaction = { 
      id: "TX" + Date.now(), 
      userId: user!.id, 
      type: 'Deposit', 
      amount: data.amount,
      coins: coinsCalculated,
      status: 'Pending', 
      timestamp: Date.now(), 
      utr: data.utr, 
      userUpiId: data.upiId, 
      screenshotUrl: data.screenshot 
    };
    setTransactions(prev => [newTx, ...prev]);
    alert(`Deposit of ₹${data.amount} submitted!`);
  };

  const handleWithdrawal = (data: { amount: number, upiId: string }) => {
    if (data.amount < 200) return alert("Minimum withdrawal is 200 coins (₹20)");
    if (user!.balance < data.amount) return alert("Insufficient balance!");
    const newTx: Transaction = { id: "TX" + Date.now(), userId: user!.id, type: 'Withdrawal', amount: data.amount / 10, coins: data.amount, status: 'Pending', timestamp: Date.now(), userUpiId: data.upiId };
    setTransactions(prev => [newTx, ...prev]);
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance - data.amount };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
    alert("Withdrawal submitted!");
  };

  const handleProcessTx = (id: string, status: 'Completed' | 'Rejected', adminMessage?: string) => {
    setTransactions(prev => prev.map(tx => {
      if (tx.id === id) {
        if (tx.status !== 'Pending') return tx;

        if (tx.type === 'Deposit' && status === 'Completed') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }

        if (tx.type === 'Withdrawal' && status === 'Rejected') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }

        const title = tx.type === 'Withdrawal' ? `Withdrawal ${status}` : `Deposit ${status}`;
        const defaultContent = status === 'Completed' ? `Your ${tx.type.toLowerCase()} of ₹${tx.amount} has been approved.` : `Your ${tx.type.toLowerCase()} of ₹${tx.amount} has been rejected.`;
        const content = adminMessage ? `${defaultContent}\n\nNote from Admin: ${adminMessage}` : defaultContent;

        const newMsg: Message = {
          id: "MSG" + Date.now(),
          userId: tx.userId,
          title,
          content,
          timestamp: Date.now(),
          isRead: false,
          type: 'Wallet'
        };
        setMessages(prevMsgs => [newMsg, ...prevMsgs]);

        return { ...tx, status };
      }
      return tx;
    }));
  };

  const handleMarkRead = (id: string) => {
    setMessages(prev => prev.map(m => m.id === id ? { ...m, isRead: true } : m));
  };

  const handleClearInbox = () => {
    if (user) {
      setMessages(prev => prev.filter(m => m.userId !== user.id));
    }
  };

  const sync = getSyncData(activeMode);
  const unreadCount = user ? messages.filter(m => m.userId === user.id && !m.isRead).length : 0;

  if (!user) return <AuthModal onAuth={handleAuth} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a] shadow-2xl overflow-x-hidden">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={true} onClose={() => setIsResultModalOpen(false)} />}
        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-md px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            {activeGame && <button onClick={() => setActiveGame(null)} className="mr-2 text-xl">❮</button>}
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center font-black">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron tracking-tighter">Ritik Club</h1>
              <p className="text-[8px] font-black text-green-500 uppercase tracking-widest">Global Protocol Active</p>
            </div>
          </div>
          <div className="text-right">
             <p className="text-[10px] text-gray-500 font-black">BALANCE</p>
             <p className="text-sm font-black text-yellow-500 font-orbitron">🪙 {user.balance.toFixed(2)}</p>
          </div>
        </header>

        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={setActiveGame} customGames={customGames} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode]} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame balance={user.balance} onUpdateBalance={(v) => setUser(u => {
             if(!u) return null;
             const updated = {...u, balance: u.balance + v};
             setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
             return updated;
          })} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame balance={user.balance} onUpdateBalance={(v) => setUser(u => {
             if(!u) return null;
             const updated = {...u, balance: u.balance + v};
             setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
             return updated;
          })} />}
          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} onUpdateUser={setUser} onRedeemGift={(code) => {
             const g = giftCodes.find(x => x.code === code);
             if (g) { 
               setUser(u => {
                 if(!u) return null;
                 const updated = {...u, balance: u.balance + g.amount};
                 setDbUsers(users => users.map(dbu => dbu.id === u.id ? updated : dbu));
                 return updated;
               });
               setGiftCodes(prev => prev.filter(x => x.code !== code)); alert("Redeemed!"); 
             }
          }} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={transactions.filter(t => t.userId === user.id)} onDeposit={handleDeposit} onWithdraw={handleWithdrawal} />}
          {activeTab === Tab.INBOX && <InboxView messages={messages.filter(m => m.userId === user.id)} onMarkRead={handleMarkRead} onClearAll={handleClearInbox} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode]} userBets={userBets} />}
          {activeTab === Tab.ADMIN && user.phone === ADMIN_PHONE && (
            <AdminView 
              overrides={adminOverrides as any} onSetOverride={(m, n) => setAdminOverrides(prev => ({ ...prev, [m]: n }))} 
              giftCodes={giftCodes} onAddGift={(g) => setGiftCodes(p => [...p, g])} onAddGame={(g) => setCustomGames(p => [...p, g])} onRemoveGame={(id) => setCustomGames(p => p.filter(x => x.id !== id))} customGames={customGames}
              pendingTxs={transactions.filter(t => t.status === 'Pending')} onProcessTx={handleProcessTx}
            />
          )}
        </main>
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} unreadCount={unreadCount} />
      </div>
    </div>
  );
};

