import React, { useState, useEffect } from 'react';

interface AviatorGameProps {
  balance: number;
  adminOverride: number | null;
  onUpdateBalance: (amount: number) => void;
  onClearOverride: () => void;
}

const AviatorGame: React.FC<AviatorGameProps> = ({ balance, adminOverride, onUpdateBalance, onClearOverride }) => {
  const [multiplier, setMultiplier] = useState(1.00);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isFlying, setIsFlying] = useState(false);
  const [isCrashed, setIsCrashed] = useState(false);
  const [crashPoint, setCrashPoint] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [hasBet, setHasBet] = useState(false);
  const [cashedOut, setCashedOut] = useState(false);

  // Realistic Simulation: Fake Live Players
  const [liveBets, setLiveBets] = useState<any[]>([]);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 30000;
      const cycleTime = now % periodDuration;
      const waitTime = 10000;
      const currentPeriod = Math.floor(now / periodDuration).toString();

      if (cycleTime < waitTime) {
        setIsFlying(false);
        setIsCrashed(false);
        setTimeLeft(Math.ceil((waitTime - cycleTime) / 1000));
        setMultiplier(1.00);
        if (cycleTime < 500) { 
           setHasBet(false);
           setCashedOut(false);
           // Update fake live bets for realism
           setLiveBets(Array(15).fill(0).map((_, i) => ({
             id: i,
             name: `Player_${Math.floor(1000 + Math.random() * 9000)}`,
             amount: [10, 50, 100, 500, 1000][Math.floor(Math.random() * 5)],
             win: null
           })));
        }
      } else {
        if (!isFlying) {
          // Determine crash point at start of flight
          let targetCrash: number;
          if (adminOverride !== null) {
            targetCrash = adminOverride;
            onClearOverride();
          } else {
            let hash = 0;
            const seed = currentPeriod + "aviator_v4";
            for (let i = 0; i < seed.length; i++) hash = ((hash << 5) - hash) + seed.charCodeAt(i);
            targetCrash = 1 + (Math.abs(hash) % 400) / 100; // 1.00 to 5.00
          }
          setCrashPoint(targetCrash);
          setIsFlying(true);
        }

        const elapsedFlight = (cycleTime - waitTime) / 1000;
        const currentMult = Math.pow(1.08, elapsedFlight);

        if (currentMult >= crashPoint) {
          setIsCrashed(true);
          setMultiplier(crashPoint);
        } else {
          setMultiplier(currentMult);
          // Randomly "Cash Out" fake players
          if (Math.random() > 0.9) {
            setLiveBets(prev => prev.map(lb => lb.win === null && Math.random() > 0.5 ? { ...lb, win: lb.amount * currentMult } : lb));
          }
        }
      }
    }, 100);
    return () => clearInterval(interval);
  }, [isFlying, adminOverride, crashPoint]);

  const handlePlaceBet = () => {
    if (!isFlying && !hasBet && balance >= betAmount) {
      onUpdateBalance(-betAmount);
      setHasBet(true);
    }
  };

  const handleCashOut = () => {
    if (isFlying && !isCrashed && hasBet && !cashedOut) {
      const win = betAmount * multiplier;
      onUpdateBalance(win);
      setCashedOut(true);
    }
  };

  return (
    <div className="p-4 space-y-4 animate-in fade-in duration-500">
      <div className="h-64 bg-[#0a0c10] rounded-[2rem] border border-red-500/20 relative overflow-hidden flex flex-col items-center justify-center">
        {!isFlying ? (
          <div className="text-center z-10">
            <p className="text-[10px] text-red-500 font-black uppercase tracking-[0.3em] mb-2">Next Flight Starts</p>
            <p className="text-6xl font-black font-orbitron text-white">{timeLeft}s</p>
          </div>
        ) : (
          <div className="text-center z-10">
            <p className={`text-7xl font-black font-orbitron transition-all duration-300 ${isCrashed ? 'text-red-600 scale-90' : 'text-white scale-110 drop-shadow-[0_0_20px_rgba(255,255,255,0.3)]'}`}>
              {multiplier.toFixed(2)}x
            </p>
            {isCrashed && <p className="text-sm font-black text-red-600 uppercase mt-2 tracking-widest animate-pulse">FLEW AWAY!</p>}
            {!isCrashed && <div className="mt-8 text-5xl animate-bounce">✈️</div>}
          </div>
        )}
      </div>

      <div className="bg-[#1e2330] p-5 rounded-[2.5rem] border border-white/5 space-y-4 shadow-2xl">
        <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-white/5">
           <button onClick={() => setBetAmount(Math.max(10, betAmount - 10))} className="w-10 h-10 bg-white/5 rounded-xl font-black text-xl">-</button>
           <span className="text-lg font-black font-orbitron">🪙 {betAmount}</span>
           <button onClick={() => setBetAmount(betAmount + 10)} className="w-10 h-10 bg-white/5 rounded-xl font-black text-xl">+</button>
        </div>

        {!isFlying ? (
          <button disabled={hasBet} onClick={handlePlaceBet} className={`w-full py-5 rounded-2xl font-black text-lg uppercase shadow-2xl transition-all active:scale-95 ${hasBet ? 'bg-gray-800 text-gray-500' : 'bg-red-600 text-white shadow-red-900/40'}`}>
            {hasBet ? 'Waiting...' : 'Bet'}
          </button>
        ) : (
          <button disabled={isCrashed || cashedOut || !hasBet} onClick={handleCashOut} className={`w-full py-5 rounded-2xl font-black text-lg uppercase shadow-2xl transition-all active:scale-95 ${isCrashed || cashedOut || !hasBet ? 'bg-gray-800 text-gray-500' : 'bg-orange-500 text-black shadow-orange-900/40'}`}>
            {cashedOut ? 'Won!' : isCrashed ? 'Lost' : `Cash Out ${(betAmount * multiplier).toFixed(1)}`}
          </button>
        )}
      </div>

      {/* Realistic Activity Feed */}
      <div className="bg-[#1e2330] rounded-3xl p-4 border border-white/5 h-40 overflow-hidden relative">
         <h4 className="text-[10px] font-black text-gray-600 uppercase mb-3 px-2">Live Player Activity</h4>
         <div className="space-y-2">
            {liveBets.map(lb => (
              <div key={lb.id} className="flex justify-between items-center bg-black/20 p-2 rounded-lg border border-white/5">
                <span className="text-[9px] font-bold text-gray-400">{lb.name}</span>
                <span className="text-[9px] font-black text-white">🪙 {lb.amount}</span>
                {lb.win ? (
                  <span className="text-[9px] font-black text-green-500">+{lb.win.toFixed(1)}</span>
                ) : (
                  <span className="text-[9px] font-bold text-gray-700">Betting...</span>
                )}
              </div>
            ))}
         </div>
         <div className="absolute bottom-0 left-0 right-0 h-12 bg-gradient-to-t from-[#1e2330] to-transparent pointer-events-none"></div>
      </div>
    </div>
  );
};

export default AviatorGame;

import React, { useState, useEffect } from 'react';

interface MinesGameProps {
  balance: number;
  adminOverride: number[] | null;
  onUpdateBalance: (amount: number) => void;
  onClearOverride: () => void;
}

const MinesGame: React.FC<MinesGameProps> = ({ balance, adminOverride, onUpdateBalance, onClearOverride }) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [mines, setMines] = useState<number[]>([]);
  const [revealed, setRevealed] = useState<number[]>([]);
  const [gameOver, setGameOver] = useState(false);
  const [mineCount, setMineCount] = useState(3);
  const [stats, setStats] = useState({ players: 0, diamonds: 0 });

  useEffect(() => {
    setStats({
      players: Math.floor(100 + Math.random() * 900),
      diamonds: Math.floor(5000 + Math.random() * 5000)
    });
  }, [isPlaying]);

  const startGame = () => {
    if (balance < bet) return;
    onUpdateBalance(-bet);

    let newMines: number[] = [];
    if (adminOverride && Array.isArray(adminOverride)) {
      newMines = adminOverride;
      onClearOverride();
    } else {
      while (newMines.length < mineCount) {
        const pos = Math.floor(Math.random() * 25);
        if (!newMines.includes(pos)) newMines.push(pos);
      }
    }

    setMines(newMines);
    setRevealed([]);
    setGameOver(false);
    setIsPlaying(true);
  };

  const handleTile = (idx: number) => {
    if (!isPlaying || revealed.includes(idx) || gameOver) return;
    if (mines.includes(idx)) {
      setGameOver(true);
      setIsPlaying(false);
    } else {
      setRevealed(prev => [...prev, idx]);
    }
  };

  const cashOut = () => {
    if (!isPlaying) return;
    const multiplier = 1 + (revealed.length * (0.2 + (mineCount * 0.1)));
    onUpdateBalance(bet * multiplier);
    setIsPlaying(false);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center px-4 bg-[#1e2330] py-3 rounded-2xl border border-white/5">
         <div className="text-center">
            <p className="text-[8px] text-gray-500 font-black uppercase">Active Players</p>
            <p className="text-sm font-black font-orbitron text-blue-500">{stats.players}</p>
         </div>
         <div className="w-px h-6 bg-white/5"></div>
         <div className="text-center">
            <p className="text-[8px] text-gray-500 font-black uppercase">Total Diamonds</p>
            <p className="text-sm font-black font-orbitron text-green-500">{stats.diamonds}</p>
         </div>
      </div>

      <div className="grid grid-cols-5 gap-2 bg-[#0a0c10] p-4 rounded-[2.5rem] border border-white/5 shadow-2xl">
        {Array(25).fill(null).map((_, i) => (
          <button 
            key={i} onClick={() => handleTile(i)}
            className={`aspect-square rounded-2xl transition-all duration-300 flex items-center justify-center text-xl active:scale-90 ${
              revealed.includes(i) ? 'bg-gradient-to-br from-blue-500 to-indigo-600 shadow-lg' : 
              gameOver && mines.includes(i) ? 'bg-red-600 animate-shake' : 
              'bg-[#1e2330] border border-white/5'
            }`}
          >
            {revealed.includes(i) ? '💎' : (gameOver && mines.includes(i)) ? '💣' : ''}
          </button>
        ))}
      </div>

      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 space-y-6">
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-black/40 p-3 rounded-xl border border-white/5">
            <p className="text-[9px] text-gray-500 uppercase font-black mb-1">Bet</p>
            <p className="text-lg font-black font-orbitron text-yellow-500">🪙 {bet}</p>
          </div>
          <select 
            disabled={isPlaying} value={mineCount} 
            onChange={(e) => setMineCount(Number(e.target.value))} 
            className="bg-black/40 p-3 rounded-xl border border-white/5 text-lg font-black font-orbitron text-white outline-none"
          >
            {[1, 3, 5, 10, 20].map(m => <option key={m} value={m} className="bg-[#1e2330]">{m} Mines</option>)}
          </select>
        </div>

        {isPlaying ? (
          <button onClick={cashOut} className="w-full py-5 bg-gradient-to-r from-yellow-600 to-yellow-500 text-black rounded-3xl font-black text-lg uppercase shadow-2xl">
            Cash Out {(bet * (1 + revealed.length * (0.2 + (mineCount * 0.1)))).toFixed(1)}
          </button>
        ) : (
          <button onClick={startGame} className="w-full py-5 bg-blue-600 text-white rounded-3xl font-black text-lg uppercase shadow-2xl">
            Start Game
          </button>
        )}
      </div>
    </div>
  );
};

