             {[0, 9].map(n => (
               <button key={n} onClick={() => onUpdateControls({...adminControls, vortex: n})} className={`py-2 rounded-lg text-[9px] font-black border ${adminControls.vortex === n ? 'bg-purple-600 border-white' : 'bg-black/20 border-white/5'}`}>Idx {n}</button>
             ))}
             <button onClick={() => onUpdateControls({...adminControls, vortex: null})} className="col-span-2 py-1 bg-white/5 text-[8px] rounded uppercase">Clear</button>
           </div>
        </div>
      </div>

      {/* REQUESTS MONITOR */}
      <div className="bg-[#1e2330] rounded-3xl p-6 border border-white/5 space-y-4">
         <h3 className="text-xs font-black font-orbitron text-green-500 uppercase">Requests Monitor ({pendingTxs.length})</h3>
         <div className="space-y-3">
            {pendingTxs.map(tx => (
              <div key={tx.id} className="bg-[#11131a] p-4 rounded-2xl border border-white/5 space-y-3">
                 <div className="flex justify-between items-start">
                    <div>
                       <p className="text-xs font-black uppercase tracking-wider">{tx.type} - ₹{tx.amount}</p>
                       <p className="text-[9px] text-blue-500 font-bold">UPI: {tx.userUpiId}</p>
                    </div>
                    {tx.screenshotUrl && <button onClick={() => setActiveImg(tx.screenshotUrl!)} className="w-10 h-10 bg-white/5 rounded-lg text-xs flex items-center justify-center">📷</button>}
                 </div>
                 <textarea placeholder="Reason/Note" value={txMessages[tx.id] || ''} onChange={(e) => setTxMessages(p => ({ ...p, [tx.id]: e.target.value }))} className="w-full bg-black/40 border border-white/5 rounded-xl p-3 text-[10px] h-16"/>
                 <div className="flex gap-2">
                    <button onClick={() => onProcessTx(tx.id, 'Completed', txMessages[tx.id])} className="flex-1 bg-green-600 py-3 rounded-xl text-[10px] font-black uppercase">Approve</button>
                    <button onClick={() => onProcessTx(tx.id, 'Rejected', txMessages[tx.id])} className="flex-1 bg-red-600/20 text-red-500 py-3 rounded-xl text-[10px] font-black uppercase">Reject</button>
                 </div>
              </div>
            ))}
         </div>
      </div>
    </div>
  );
};

export default AdminView;

import React, { useState, useEffect } from 'react';
import { Tab } from '../types.ts';

interface CricketGameProps {
  balance: number;
  adminOverride: number | null;
  onUpdateBalance: (a: number) => void;
  onClearOverride: () => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
}

const CricketGame: React.FC<CricketGameProps> = ({ balance, adminOverride, onUpdateBalance, onClearOverride, hasAccess, setTab }) => {
  const [bet, setBet] = useState(10);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isDrawPhase, setIsDrawPhase] = useState(false);
  const [lastRun, setLastRun] = useState<number | null>(null);
  const [currentPeriod, setCurrentPeriod] = useState("");
  const [myPrediction, setMyPrediction] = useState<number | null>(null);
  const [myBetAmount, setMyBetAmount] = useState(0);
  const [liveBets, setLiveBets] = useState<any[]>([]);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 30000;
      const cycleTime = now % periodDuration;
      const bettingTime = 20000;
      const period = Math.floor(now / periodDuration).toString();

      setCurrentPeriod(period);

      if (cycleTime < bettingTime) {
        setIsDrawPhase(false);
        setTimeLeft(Math.ceil((bettingTime - cycleTime) / 1000));
        if (cycleTime < 1000) {
           setLiveBets(Array(8).fill(0).map((_, i) => ({
             id: i,
             user: "User_"+Math.floor(100+Math.random()*900),
             predict: [0, 1, 2, 4, 6][Math.floor(Math.random()*5)],
             won: null
           })));
        }
      } else {
        if (!isDrawPhase) {
          let actualRun: number;
          if (adminOverride !== null) {
            actualRun = adminOverride;
            onClearOverride();
          } else {
            let hash = 0;
            const seed = period + "cricket_v1";
            for (let i = 0; i < seed.length; i++) hash = ((hash << 5) - hash) + seed.charCodeAt(i);
            actualRun = [0, 1, 2, 4, 6][Math.abs(hash) % 5];
          }
          setLastRun(actualRun);

          if (myPrediction !== null) {
            if (myPrediction === actualRun) {
              const mult = actualRun === 6 ? 6 : actualRun === 4 ? 4 : 2;
              onUpdateBalance(myBetAmount * mult);
            }
            setMyPrediction(null);
            setMyBetAmount(0);
          }
          // Update fake wins
          setLiveBets(p => p.map(b => b.predict === actualRun ? {...b, won: true} : {...b, won: false}));
        }
        setIsDrawPhase(true);
        setTimeLeft(Math.ceil((periodDuration - cycleTime) / 1000));
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [isDrawPhase, myPrediction, myBetAmount, adminOverride]);

  const placePrediction = (predict: number) => {
    if (!hasAccess) return;
    if (!isDrawPhase && balance >= bet && myPrediction === null) {
      onUpdateBalance(-bet);
      setMyPrediction(predict);
      setMyBetAmount(bet);
