import React, { useState, useEffect } from 'react';
import { Tab } from '../types.ts';

interface AviatorGameProps {
  balance: number;
  adminOverride: number | null;
  onUpdateBalance: (amount: number) => void;
  onClearOverride: () => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
}

const AviatorGame: React.FC<AviatorGameProps> = ({ balance, adminOverride, onUpdateBalance, onClearOverride, hasAccess, setTab }) => {
  const [multiplier, setMultiplier] = useState(1.00);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isFlying, setIsFlying] = useState(false);
  const [isCrashed, setIsCrashed] = useState(false);
  const [crashPoint, setCrashPoint] = useState(1.00);
  const [betAmount, setBetAmount] = useState(10);
  const [hasBet, setHasBet] = useState(false);
  const [cashedOut, setCashedOut] = useState(false);
  const [liveBets, setLiveBets] = useState<any[]>([]);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 30000;
      const cycleTime = now % periodDuration;
      const waitTime = 10000;
      const currentPeriod = Math.floor(now / periodDuration).toString();

      if (cycleTime < waitTime) {
        setIsFlying(false);
        setIsCrashed(false);
        setTimeLeft(Math.ceil((waitTime - cycleTime) / 1000));
        setMultiplier(1.00);
        if (cycleTime < 500) { 
           setHasBet(false);
           setCashedOut(false);
           setLiveBets(Array(15).fill(0).map((_, i) => ({ id: i, name: `User_${Math.floor(100+Math.random()*900)}`, amount: [10, 50, 100][Math.floor(Math.random()*3)], win: null })));
        }
      } else {
        if (!isFlying) {
          let targetCrash: number;
          if (adminOverride !== null) {
            targetCrash = adminOverride;
            onClearOverride();
          } else {
            let hash = 0;
            const seed = currentPeriod + "aviator_v4";
            for (let i = 0; i < seed.length; i++) hash = ((hash << 5) - hash) + seed.charCodeAt(i);
            targetCrash = 1 + (Math.abs(hash) % 400) / 100;
          }
          setCrashPoint(targetCrash);
          setIsFlying(true);
        }

        const elapsedFlight = (cycleTime - waitTime) / 1000;
        const currentMult = Math.pow(1.08, elapsedFlight);

        if (currentMult >= crashPoint) {
          setIsCrashed(true);
          setMultiplier(crashPoint);
        } else {
          setMultiplier(currentMult);
          if (Math.random() > 0.95) {
            setLiveBets(p => p.map(lb => lb.win === null && Math.random() > 0.5 ? { ...lb, win: lb.amount * currentMult } : lb));
          }
        }
      }
    }, 100);
    return () => clearInterval(interval);
  }, [isFlying, adminOverride, crashPoint]);

  const handlePlaceBet = () => {
    if (!hasAccess) return;
    if (!isFlying && !hasBet && balance >= betAmount) {
      onUpdateBalance(-betAmount);
      setHasBet(true);
    }
  };

  const handleCashOut = () => {
    if (isFlying && !isCrashed && hasBet && !cashedOut) {
      const win = betAmount * multiplier;
      onUpdateBalance(win);
      setCashedOut(true);
    }
  };

  return (
    <div className="p-4 space-y-4 animate-in fade-in duration-500">
      <div className="h-64 bg-[#0a0c10] rounded-[2rem] border border-red-500/20 relative overflow-hidden flex flex-col items-center justify-center">
        {!isFlying ? (
          <div className="text-center z-10">
            <p className="text-[10px] text-red-500 font-black uppercase tracking-[0.3em] mb-2">Next Flight Starts</p>
            <p className="text-6xl font-black font-orbitron text-white">{timeLeft}s</p>
          </div>
        ) : (
          <div className="text-center z-10">
            <p className={`text-7xl font-black font-orbitron transition-all ${isCrashed ? 'text-red-600 scale-90' : 'text-white scale-110 drop-shadow-[0_0_20px_rgba(255,255,255,0.3)]'}`}>
              {multiplier.toFixed(2)}x
            </p>
          </div>
        )}
      </div>

      <div className="bg-[#1e2330] p-5 rounded-[2.5rem] border border-white/5 space-y-4 shadow-2xl">
        {!hasAccess ? (
           <div className="text-center py-4 space-y-3">
              <p className="text-[10px] text-gray-500 font-black uppercase">Flight Restricted</p>
              <button onClick={() => setTab(Tab.WALLET)} className="w-full py-4 bg-red-600 rounded-2xl font-black text-[10px] uppercase">Deposit ₹20 to Fly</button>
           </div>
        ) : (
           <>
              <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl border border-white/5">
                 <button onClick={() => setBetAmount(Math.max(10, betAmount - 10))} className="w-10 h-10 bg-white/5 rounded-xl font-black text-xl">-</button>
                 <span className="text-lg font-black font-orbitron">🪙 {betAmount}</span>
                 <button onClick={() => setBetAmount(betAmount + 10)} className="w-10 h-10 bg-white/5 rounded-xl font-black text-xl">+</button>
              </div>
              {!isFlying ? (
                <button disabled={hasBet} onClick={handlePlaceBet} className={`w-full py-5 rounded-2xl font-black text-lg uppercase shadow-2xl ${hasBet ? 'bg-gray-800 text-gray-500' : 'bg-red-600 text-white'}`}>{hasBet ? 'Waiting...' : 'Bet'}</button>
              ) : (
                <button disabled={isCrashed || cashedOut || !hasBet} onClick={handleCashOut} className={`w-full py-5 rounded-2xl font-black text-lg uppercase shadow-2xl ${isCrashed || cashedOut || !hasBet ? 'bg-gray-800 text-gray-500' : 'bg-orange-500 text-black'}`}>{cashedOut ? 'Won!' : isCrashed ? 'Lost' : `Cash Out ${(betAmount * multiplier).toFixed(1)}`}</button>
              )}
           </>
        )}
      </div>

      <div className="bg-[#1e2330] rounded-3xl p-4 border border-white/5 h-40 overflow-hidden relative">
         <h4 className="text-[10px] font-black text-gray-600 uppercase mb-3 px-2 tracking-widest">Live Activity</h4>
         <div className="space-y-2">
            {liveBets.map(lb => (
              <div key={lb.id} className="flex justify-between items-center bg-black/20 p-2 rounded-lg text-[9px]">
                <span className="text-gray-400 font-bold">{lb.name}</span>
                <span className="text-white font-black">🪙 {lb.amount}</span>
                {lb.win ? <span className="text-green-500 font-black">+{lb.win.toFixed(1)}</span> : <span className="text-gray-700 font-bold">Betting...</span>}
              </div>
            ))}
         </div>
      </div>
    </div>
  );
};

export default AviatorGame;

import React, { useState, useEffect } from 'react';
import { Tab } from '../types.ts';

interface MinesGameProps {
  balance: number;
  adminOverride: number[] | null;
  onUpdateBalance: (amount: number) => void;
  onClearOverride: () => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
}

const MinesGame: React.FC<MinesGameProps> = ({ balance, adminOverride, onUpdateBalance, onClearOverride, hasAccess, setTab }) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [mines, setMines] = useState<number[]>([]);
  const [revealed, setRevealed] = useState<number[]>([]);
  const [gameOver, setGameOver] = useState(false);
  const [mineCount, setMineCount] = useState(3);

  const startGame = () => {
    if (!hasAccess || balance < bet) return;
    onUpdateBalance(-bet);

    let newMines: number[] = [];
    if (adminOverride && Array.isArray(adminOverride)) {
      newMines = adminOverride;
      onClearOverride();
    } else {
      while (newMines.length < mineCount) {
        const pos = Math.floor(Math.random() * 25);
        if (!newMines.includes(pos)) newMines.push(pos);
      }
    }
    setMines(newMines); setRevealed([]); setGameOver(false); setIsPlaying(true);
  };

  const handleTile = (idx: number) => {
    if (!isPlaying || revealed.includes(idx) || gameOver) return;
    if (mines.includes(idx)) { setGameOver(true); setIsPlaying(false); }
    else setRevealed(prev => [...prev, idx]);
  };

  const cashOut = () => {
    if (!isPlaying) return;
    const multiplier = 1 + (revealed.length * (0.2 + (mineCount * 0.1)));
    onUpdateBalance(bet * multiplier); setIsPlaying(false);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <div className="grid grid-cols-5 gap-2 bg-[#0a0c10] p-4 rounded-[2.5rem] border border-white/5 shadow-2xl">
        {Array(25).fill(null).map((_, i) => (
          <button 
            key={i} onClick={() => handleTile(i)}
            className={`aspect-square rounded-2xl transition-all duration-300 flex items-center justify-center text-xl ${revealed.includes(i) ? 'bg-gradient-to-br from-blue-500 to-indigo-600 shadow-lg' : gameOver && mines.includes(i) ? 'bg-red-600' : 'bg-[#1e2330] border border-white/5'}`}
          >
            {revealed.includes(i) ? '💎' : (gameOver && mines.includes(i)) ? '💣' : ''}
          </button>
        ))}
      </div>

      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 space-y-6">
        {!hasAccess ? (
           <div className="text-center py-4 space-y-3">
              <p className="text-[10px] text-gray-500 font-black uppercase">Mines Blocked</p>
              <button onClick={() => setTab(Tab.WALLET)} className="w-full py-4 bg-yellow-600 text-black rounded-2xl font-black text-[10px] uppercase">Deposit ₹20 to Unblock</button>
           </div>
        ) : (
           <>
              <div className="grid grid-cols-2 gap-4">
                <div className="bg-black/40 p-3 rounded-xl border border-white/5"><p className="text-[9px] text-gray-500 uppercase font-black mb-1">Bet</p><p className="text-lg font-black font-orbitron text-yellow-500">🪙 {bet}</p></div>
                <select disabled={isPlaying} value={mineCount} onChange={(e) => setMineCount(Number(e.target.value))} className="bg-black/40 p-3 rounded-xl border border-white/5 text-lg font-black font-orbitron text-white outline-none">
                  {[1, 3, 5, 10, 20].map(m => <option key={m} value={m}>{m} Mines</option>)}
                </select>
              </div>
              {isPlaying ? (
                <button onClick={cashOut} className="w-full py-5 bg-gradient-to-r from-yellow-600 to-yellow-500 text-black rounded-3xl font-black text-lg uppercase shadow-2xl">Cash Out {(bet * (1 + revealed.length * (0.2 + (mineCount * 0.1)))).toFixed(1)}</button>
              ) : (
                <button onClick={startGame} className="w-full py-5 bg-blue-600 text-white rounded-3xl font-black text-lg uppercase shadow-2xl">Start Game</button>
              )}
           </>
        )}
      </div>
    </div>
  );
};

export default MinesGame;

import React, { useState, useEffect } from 'react';
import { Tab } from '../types.ts';

interface ChickenGameProps {
  balance: number;
  adminOverride: any;
  onUpdateBalance: (a: number) => void;
  onClearOverride: () => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
}

const ChickenGame: React.FC<ChickenGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab }) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [pos, setPos] = useState({ x: 2, y: 4 });
  const [obstacles, setObstacles] = useState<number[]>([]);
  const [gameOver, setGameOver] = useState(false);
  const [won, setWon] = useState(false);

  const startGame = () => {
    if (!hasAccess || balance < bet) return;
    onUpdateBalance(-bet);
    setIsPlaying(true); setGameOver(false); setWon(false); setPos({ x: 2, y: 4 });
    const obs = Array(7).fill(0).map(() => Math.floor(Math.random()*25)).filter(o => o !== 22);
    setObstacles(obs);
  };

  const move = (dx: number, dy: number) => {
    if (!isPlaying || gameOver || won) return;
    const newX = Math.max(0, Math.min(4, pos.x + dx));
    const newY = Math.max(0, Math.min(4, pos.y + dy));
    const idx = newY * 5 + newX;
    if (obstacles.includes(idx)) { setGameOver(true); setIsPlaying(false); }
    else {
      setPos({ x: newX, y: newY });
      if (newY === 0) { setWon(true); setIsPlaying(false); onUpdateBalance(bet * 5); }
    }
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-700">
      <div className="grid grid-cols-5 gap-2 bg-[#0a0c10] p-4 rounded-[2.5rem] border border-white/5 shadow-2xl relative">
        {Array(25).fill(null).map((_, i) => {
          const x = i % 5; const y = Math.floor(i / 5);
          const isPlayer = pos.x === x && pos.y === y;
          return <div key={i} className={`aspect-square rounded-2xl flex items-center justify-center text-2xl relative border ${y === 0 ? 'bg-green-500/5 border-green-500/20' : 'bg-[#1e2330] border-white/5'}`}>{isPlayer && '🍗'}</div>;
        })}
      </div>
      <div className="bg-[#1e2330] rounded-[3rem] p-6 border border-white/5 space-y-4">
        {!hasAccess ? (
           <button onClick={() => setTab(Tab.WALLET)} className="w-full py-4 bg-orange-600 rounded-2xl font-black text-[10px] uppercase">Deposit ₹20 to Pathfind</button>
        ) : (
           <>
              <div className="grid grid-cols-3 gap-3">
                <div/><button onClick={()=>move(0,-1)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-xl flex items-center justify-center border border-white/10">▲</button><div/>
                <button onClick={()=>move(-1,0)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-xl flex items-center justify-center border border-white/10">◀</button>
                <button onClick={()=>move(0,1)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-xl flex items-center justify-center border border-white/10">▼</button>
                <button onClick={()=>move(1,0)} disabled={!isPlaying} className="bg-white/5 aspect-square rounded-xl flex items-center justify-center border border-white/10">▶</button>
              </div>
              <button onClick={startGame} disabled={isPlaying} className="w-full py-5 bg-orange-600 rounded-2xl font-black uppercase shadow-xl mt-4">{isPlaying ? 'Moving...' : 'Start Path'}</button>
           </>
        )}
      </div>
    </div>
  );
};

export default ChickenGame;

import React, { useState, useEffect, useCallback } from 'react';
import { Tab, UserState, GameResult, ColorType, UserBet, GameMode, GameType, GiftCode, CustomGame, Transaction, Message } from './types.ts';
import { COLORS_BY_NUMBER } from './constants.tsx';
import Navigation from './components/Navigation.tsx';
import HomeView from './views/HomeView.tsx';
import HistoryView from './views/HistoryView.tsx';
import WalletView from './views/WalletView.tsx';
import ProfileView from './views/ProfileView.tsx';
import AdminView from './views/AdminView.tsx';
import InboxView from './views/InboxView.tsx';
import AuthModal from './components/AuthModal.tsx';
import ResultModal from './components/ResultModal.tsx';
import WinGoGame from './views/WinGoGame.tsx';
import AviatorGame from './views/AviatorGame.tsx';
import MinesGame from './views/MinesGame.tsx';
import CricketGame from './views/CricketGame.tsx';
import VortexGame from './views/VortexGame.tsx';
import ChickenGame from './views/ChickenGame.tsx';

const ADMIN_PHONE = "6207559408";
const WELCOME_BONUS = 25;
const MODE_DURATIONS: Record<GameMode, number> = { '30sec': 30, '1min': 60, '3min': 180, '5min': 300 };

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.HOME);
  const [activeGame, setActiveGame] = useState<GameType | null>(null);
  const [activeMode, setActiveMode] = useState<GameMode>('30sec');

  const [dbUsers, setDbUsers] = useState<UserState[]>(() => {
    const saved = localStorage.getItem('rc_users_db');
    return saved ? JSON.parse(saved) : [];
  });

  const [user, setUser] = useState<UserState | null>(() => {
    const saved = localStorage.getItem('rc_current_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [userBets, setUserBets] = useState<UserBet[]>(() => {
    const saved = localStorage.getItem('rc_bets');
    return saved ? JSON.parse(saved) : [];
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('rc_tx');
    return saved ? JSON.parse(saved) : [];
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('rc_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [giftCodes, setGiftCodes] = useState<GiftCode[]>(() => {
    const saved = localStorage.getItem('rc_gifts');
    return saved ? JSON.parse(saved) : [];
  });

  const [customGames, setCustomGames] = useState<CustomGame[]>(() => {
    const saved = localStorage.getItem('rc_custom_games');
    return saved ? JSON.parse(saved) : [];
  });

  // Master Control Hub
  const [adminControls, setAdminControls] = useState<Record<string, any>>({
    wingo: {},
    aviator: null,
    mines: null,
    cricket: null,
    vortex: null,
    chicken: null
  });

  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [lastProcessedPeriod, setLastProcessedPeriod] = useState<Record<string, string>>({});
  const [lastResult, setLastResult] = useState<GameResult | null>(null);
  const [lastProfit, setLastProfit] = useState<number>(0);
  const [results, setResults] = useState<Record<string, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });

  // Persist State
  useEffect(() => {
    localStorage.setItem('rc_users_db', JSON.stringify(dbUsers));
    if (user) localStorage.setItem('rc_current_session', JSON.stringify(user));
  }, [user, dbUsers]);

  useEffect(() => {
    localStorage.setItem('rc_bets', JSON.stringify(userBets));
    localStorage.setItem('rc_tx', JSON.stringify(transactions));
    localStorage.setItem('rc_messages', JSON.stringify(messages));
    localStorage.setItem('rc_gifts', JSON.stringify(giftCodes));
    localStorage.setItem('rc_custom_games', JSON.stringify(customGames));
  }, [userBets, transactions, messages, giftCodes, customGames]);

  // Derived Property: Has the user deposited at least 20 INR?
  const totalApprovedInr = transactions
    .filter(t => t.userId === user?.id && t.type === 'Deposit' && t.status === 'Completed')
    .reduce((sum, t) => sum + t.amount, 0);
  const hasAccess = totalApprovedInr >= 20;

  const getSyncData = (mode: GameMode) => {
    const now = Date.now();
    const duration = MODE_DURATIONS[mode];
    const periodTimestamp = Math.floor(now / (duration * 1000));
    const timeLeft = duration - (Math.floor(now / 1000) % duration);
    const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    return { periodId: `${dateStr}${mode}${periodTimestamp}`, timeLeft };
  };

  const processDraw = useCallback((mode: GameMode, period: string) => {
    const currentBets = userBets.filter(b => b.mode === mode && b.period === period && b.status === 'Pending');

    let winningNum: number;
    const override = adminControls.wingo[mode];

    if (override !== undefined && override !== null) {
      winningNum = override;
      setAdminControls(prev => ({ ...prev, wingo: { ...prev.wingo, [mode]: null } }));
    } else {
      let minPayout = Infinity;
      let candidates: number[] = [];
      for (let n = 0; n <= 9; n++) {
        let totalHousePayout = 0;
        const colors = COLORS_BY_NUMBER[n] as ColorType[];
        const bs = n >= 5 ? 'Big' : 'Small';
        currentBets.forEach(bet => {
          if (typeof bet.selection === 'number' && bet.selection === n) totalHousePayout += bet.amount * 8.92;
          else if (bet.selection === 'Big' || bet.selection === 'Small') {
            if (bet.selection === bs) totalHousePayout += bet.amount * 1.96;
          } else if (colors.includes(bet.selection as ColorType)) {
            let mult = 1.96;
            if ((n === 0 || n === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
            if (bet.selection === ColorType.VIOLET) mult = 4.41;
            totalHousePayout += bet.amount * mult;
          }
        });
        if (totalHousePayout < minPayout) { minPayout = totalHousePayout; candidates = [n]; }
        else if (totalHousePayout === minPayout) candidates.push(n);
      }
      winningNum = candidates[Math.floor(Math.random() * candidates.length)];
    }

    const result: GameResult = {
      id: "RES" + Math.random().toString(36).substr(2, 5).toUpperCase(),
      period,
      number: winningNum,
      colors: COLORS_BY_NUMBER[winningNum] as ColorType[],
      bigSmall: winningNum >= 5 ? 'Big' : 'Small',
      timestamp: Date.now()
    };

    setResults(prev => ({ ...prev, [mode]: [result, ...prev[mode]].slice(0, 50) }));

    let totalProfit = 0;
    let hadBet = false;
    currentBets.forEach(bet => {
      hadBet = true;
      let win = false;
      let mult = 0;
      if (typeof bet.selection === 'number') { if (bet.selection === winningNum) { win = true; mult = 8.92; } }
      else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.96; } }
      else if (result.colors.includes(bet.selection as ColorType)) {
        win = true; mult = 1.96;
        if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
        if (bet.selection === ColorType.VIOLET) mult = 4.41;
      }
      if (win) totalProfit += (bet.amount * mult);
    });

    setUserBets(prev => prev.map(bet => {
      if (bet.mode === mode && bet.period === period && bet.status === 'Pending') {
        let win = false;
        let mult = 0;
        if (typeof bet.selection === 'number') { if (bet.selection === winningNum) { win = true; mult = 8.92; } }
        else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.96; } }
        else if (result.colors.includes(bet.selection as ColorType)) {
          win = true; mult = 1.96;
          if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
          if (bet.selection === ColorType.VIOLET) mult = 4.41;
        }
        if (win) return { ...bet, status: 'Win', payout: bet.amount * mult };
        return { ...bet, status: 'Loss', payout: 0 };
      }
      return bet;
    }));

    if (totalProfit > 0) {
      setUser(curr => {
        if (!curr) return null;
        const updated = { ...curr, balance: curr.balance + totalProfit };
        setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
        return updated;
      });
    }

    if (activeGame === GameType.WINGO && mode === activeMode && hadBet) {
      setLastResult(result); 
      setLastProfit(totalProfit); 
      setIsResultModalOpen(true);
    }
  }, [activeGame, activeMode, userBets, adminControls]);

  useEffect(() => {
    const interval = setInterval(() => {
      (Object.keys(MODE_DURATIONS) as GameMode[]).forEach(mode => {
        const { periodId } = getSyncData(mode);
        if (lastProcessedPeriod[mode] && lastProcessedPeriod[mode] !== periodId) {
          processDraw(mode, lastProcessedPeriod[mode]);
        }
        setLastProcessedPeriod(prev => ({ ...prev, [mode]: periodId }));
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lastProcessedPeriod, processDraw]);

  const updateBalance = (amount: number) => {
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance + amount };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
  };

  // Fix: handleBet function handles placing bets, deducts balance, and updates total turnover for VIP calculation.
  const handleBet = (betData: { selection: any, amount: number }) => {
    if (!user) return;
    if (user.balance < betData.amount) {
      alert("Insufficient balance!");
      return;
    }

    const { periodId } = getSyncData(activeMode);

    const newBet: UserBet = {
      id: "BET" + Math.random().toString(36).substr(2, 5).toUpperCase(),
      game: GameType.WINGO,
      period: periodId,
      mode: activeMode,
      amount: betData.amount,
      selection: betData.selection,
      status: 'Pending',
      timestamp: Date.now()
    };

    setUserBets(prev => [newBet, ...prev]);

    setUser(curr => {
      if (!curr) return null;
      const updated = { 
        ...curr, 
        balance: curr.balance - betData.amount,
        totalTurnover: curr.totalTurnover + betData.amount 
      };
      setDbUsers(users => users.map(u => u.id === curr.id ? updated : u));
      return updated;
    });
  };

  const handleProcessTx = (id: string, status: 'Completed' | 'Rejected', adminMessage?: string) => {
    setTransactions(prev => prev.map(tx => {
      if (tx.id === id) {
        if (tx.status !== 'Pending') return tx;
        if (tx.type === 'Deposit' && status === 'Completed') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }
        if (tx.type === 'Withdrawal' && status === 'Rejected') {
          setDbUsers(users => users.map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }
        const title = tx.type === 'Withdrawal' ? `Withdrawal ${status}` : `Deposit ${status}`;
        const content = adminMessage ? `Status Update: ${status}\nNote: ${adminMessage}` : `Status Update: ${status}`;
        const newMsg: Message = { id: "MSG" + Date.now(), userId: tx.userId, title, content, timestamp: Date.now(), isRead: false, type: 'Wallet' };
        setMessages(prevMsgs => [newMsg, ...prevMsgs]);
        return { ...tx, status };
      }
      return tx;
    }));
  };

  const sync = getSyncData(activeMode);
  const unreadCount = user ? messages.filter(m => m.userId === user.id && !m.isRead).length : 0;

  if (!user) return <AuthModal onAuth={(p, pass, reg, ref) => {
    if (reg) {
      const newUser: UserState = { id: "U"+Date.now(), phone: p, password: pass, balance: WELCOME_BONUS, referralCode: ref || "RC"+Math.random(), vipLevel: 1, totalTurnover: 0 };
      setDbUsers(prev => [...prev, newUser]); setUser(newUser);
    } else {
      const u = dbUsers.find(x => x.phone === p && x.password === pass);
      if (u) setUser(u); else alert("Wrong details");
    }
  }} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a] shadow-2xl overflow-x-hidden">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={true} onClose={() => setIsResultModalOpen(false)} />}

        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-md px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            {activeGame && <button onClick={() => setActiveGame(null)} className="mr-2 text-xl">❮</button>}
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center font-black">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron tracking-tighter">Ritik Club</h1>
              <p className="text-[8px] font-black text-green-500 uppercase tracking-widest">Master Protocol v4.5</p>
            </div>
          </div>
          <div className="text-right">
             <p className="text-[10px] text-gray-500 font-black">BALANCE</p>
             <p className="text-sm font-black text-yellow-500 font-orbitron">🪙 {user.balance.toFixed(2)}</p>
          </div>
        </header>

        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={setActiveGame} customGames={customGames} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame hasAccess={hasAccess} setTab={setActiveTab} activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode]} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.aviator} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, aviator: null}))} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.mines} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, mines: null}))} />}
          {activeTab === Tab.HOME && activeGame === GameType.CRICKET && <CricketGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.cricket} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, cricket: null}))} />}
          {activeTab === Tab.HOME && activeGame === GameType.VORTEX && <VortexGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.vortex} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, vortex: null}))} />}
          {activeTab === Tab.HOME && activeGame === GameType.CHICKEN && <ChickenGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.chicken} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, chicken: null}))} />}

          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} onUpdateUser={setUser} onRedeemGift={(code) => {
             const g = giftCodes.find(x => x.code === code);
             if (g) { updateBalance(g.amount); setGiftCodes(prev => prev.filter(x => x.code !== code)); alert("Success!"); }
          }} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={transactions.filter(t => t.userId === user.id)} onDeposit={(d) => {
             const newTx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Deposit', amount: d.amount, coins: d.amount*10, status: 'Pending', timestamp: Date.now(), utr: d.utr, userUpiId: d.upiId, screenshotUrl: d.screenshot };
             setTransactions(p => [newTx, ...p]);
          }} onWithdraw={(d) => {
             const newTx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Withdrawal', amount: d.amount/10, coins: d.amount, status: 'Pending', timestamp: Date.now(), userUpiId: d.upiId };
             setTransactions(p => [newTx, ...p]); updateBalance(-d.amount);
          }} />}
          {activeTab === Tab.INBOX && <InboxView messages={messages.filter(m => m.userId === user.id)} onMarkRead={(id) => setMessages(p => p.map(m => m.id === id ? {...m, isRead: true} : m))} onClearAll={() => setMessages(p => p.filter(m => m.userId !== user.id))} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode]} userBets={userBets} />}
          {activeTab === Tab.ADMIN && user.phone === ADMIN_PHONE && (
            <AdminView 
              adminControls={adminControls} onUpdateControls={setAdminControls}
              giftCodes={giftCodes} onAddGift={(g) => setGiftCodes(p => [...p, g])} onAddGame={(g) => setCustomGames(p => [...p, g])} onRemoveGame={(id) => setCustomGames(p => p.filter(x => x.id !== id))} customGames={customGames}
              pendingTxs={transactions.filter(t => t.status === 'Pending')} onProcessTx={handleProcessTx}
            />
          )}
        </main>
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} unreadCount={unreadCount} />
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useState, useRef } from 'react';
import { GameResult } from '../types.ts';
import { COLOR_CONFIG } from '../constants.tsx';

interface ResultModalProps {
  result: GameResult | null;
  userProfit: number;
  hasBet: boolean;
  onClose: () => void;
}

const ResultModal: React.FC<ResultModalProps> = ({ result, userProfit, hasBet, onClose }) => {
  const [show, setShow] = useState(false);
  const timerRef = useRef<any>(null);

  const triggerClose = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    setShow(false);
    setTimeout(onClose, 300);
  };

  useEffect(() => {
    if (result && hasBet) {
      setShow(true);
      // Automatically close after 3 seconds
      timerRef.current = setTimeout(() => {
        triggerClose();
      }, 3000);

      return () => {
        if (timerRef.current) clearTimeout(timerRef.current);
      };
    }
  }, [result, hasBet]);

  if (!result || !hasBet) return null;

  const mainColor = result.colors[0] as keyof typeof COLOR_CONFIG;
  const colorData = COLOR_CONFIG[mainColor];
  const isWin = userProfit > 0;

  return (
    <div className={`fixed inset-0 z-[110] flex items-center justify-center px-6 transition-all duration-300 ${show ? 'bg-black/80 backdrop-blur-md opacity-100' : 'bg-transparent opacity-0 pointer-events-none'}`}>
      <div className={`w-full max-w-sm bg-[#1e2330] rounded-[3rem] overflow-hidden border border-white/10 shadow-[0_0_100px_rgba(0,0,0,0.8)] transition-all duration-500 transform ${show ? 'scale-100 translate-y-0' : 'scale-75 translate-y-20'} ${!isWin ? 'animate-loss-result' : ''}`}>

        {/* Header Section */}
