  const [adminControls, setAdminControls] = useState<Record<string, any>>({
    wingo: {},
    aviator: null,
    mines: null,
    cricket: null,
    vortex: null,
    chicken: null,
    dragonTiger: null,
    k3: null
  });

  const [isResultModalOpen, setIsResultModalOpen] = useState(false);
  const [lastProcessedPeriod, setLastProcessedPeriod] = useState<Record<string, string>>({});
  const [lastResult, setLastResult] = useState<GameResult | null>(null);
  const [lastProfit, setLastProfit] = useState<number>(0);
  const [results, setResults] = useState<Record<string, GameResult[]>>({
    '30sec': [], '1min': [], '3min': [], '5min': []
  });

  const playSound = (key: keyof typeof SOUNDS) => {
    if (!soundEnabled) return;
    const audio = new Audio(SOUNDS[key]);
    audio.volume = 0.4;
    audio.play().catch(() => {});
  };

  useEffect(() => {
    localStorage.setItem('rc_users_db', JSON.stringify(dbUsers || []));
    if (user) localStorage.setItem('rc_current_session', JSON.stringify(user));
  }, [user, dbUsers]);

  useEffect(() => {
    localStorage.setItem('rc_bets', JSON.stringify(userBets || []));
    localStorage.setItem('rc_tx', JSON.stringify(transactions || []));
    localStorage.setItem('rc_messages', JSON.stringify(messages || []));
    localStorage.setItem('rc_gifts', JSON.stringify(giftCodes || []));
    localStorage.setItem('rc_custom_games', JSON.stringify(customGames || []));
  }, [userBets, transactions, messages, giftCodes, customGames]);

  const totalApprovedInr = (transactions || [])
    .filter(t => t.userId === user?.id && t.type === 'Deposit' && t.status === 'Completed')
    .reduce((sum, t) => sum + t.amount, 0);
  const hasAccess = totalApprovedInr >= 20;

  // Helper to notify admin
  const notifyAdmin = useCallback((title: string, content: string) => {
    const adminUser = dbUsers.find(u => u.phone === ADMIN_PHONE);
    if (!adminUser) return;

    const newMsg: Message = {
      id: "ADMIN_NOTIF_" + Date.now() + Math.random(),
      userId: adminUser.id,
      title: `🚨 ${title}`,
      content: content,
      timestamp: Date.now(),
      isRead: false,
      type: 'System'
    };

    setMessages(prev => [newMsg, ...(prev || [])]);
  }, [dbUsers]);

  const getSyncData = (mode: GameMode) => {
    const now = Date.now();
    const duration = MODE_DURATIONS[mode];
    const periodTimestamp = Math.floor(now / (duration * 1000));
    const timeLeft = duration - (Math.floor(now / 1000) % duration);
    const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    return { periodId: `${dateStr}${mode}${periodTimestamp}`, timeLeft };
  };

  const processDraw = useCallback((mode: GameMode, period: string) => {
    const currentBets = (userBets || []).filter(b => b.mode === mode && b.period === period && b.status === 'Pending');

    let winningNum: number;
    const override = adminControls.wingo[mode];

    if (override !== undefined && override !== null) {
      winningNum = override;
      setAdminControls(prev => ({ ...prev, wingo: { ...prev.wingo, [mode]: null } }));
    } else {
      let minPayout = Infinity;
      let candidates: number[] = [];
      for (let n = 0; n <= 9; n++) {
        let totalHousePayout = 0;
        const colors = COLORS_BY_NUMBER[n] as ColorType[];
        const bs = n >= 5 ? 'Big' : 'Small';
        currentBets.forEach(bet => {
          if (typeof bet.selection === 'number' && bet.selection === n) totalHousePayout += bet.amount * 8.92;
          else if (bet.selection === 'Big' || bet.selection === 'Small') {
            if (bet.selection === bs) totalHousePayout += bet.amount * 1.96;
          } else if (colors.includes(bet.selection as ColorType)) {
            let mult = 1.96;
            if ((n === 0 || n === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
            if (bet.selection === ColorType.VIOLET) mult = 4.41;
            totalHousePayout += bet.amount * mult;
          }
        });
        if (totalHousePayout < minPayout) { minPayout = totalHousePayout; candidates = [n]; }
        else if (totalHousePayout === minPayout) candidates.push(n);
      }
      winningNum = candidates[Math.floor(Math.random() * candidates.length)];
    }

    const result: GameResult = {
      id: "RES" + Math.random().toString(36).substr(2, 5).toUpperCase(),
      period,
      number: winningNum,
      colors: COLORS_BY_NUMBER[winningNum] as ColorType[],
      bigSmall: winningNum >= 5 ? 'Big' : 'Small',
      timestamp: Date.now()
    };

    setResults(prev => ({ ...prev, [mode]: [result, ...(prev[mode] || [])].slice(0, 50) }));

    let totalProfit = 0;
    let hadBet = false;
    currentBets.forEach(bet => {
      hadBet = true;
      let win = false;
      let mult = 0;
      if (typeof bet.selection === 'number') { if (bet.selection === winningNum) { win = true; mult = 8.92; } }
      else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.96; } }
      else if (result.colors.includes(bet.selection as ColorType)) {
        win = true; mult = 1.96;
        if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
        if (bet.selection === ColorType.VIOLET) mult = 4.41;
      }
      if (win) totalProfit += (bet.amount * mult);
    });

    setUserBets(prev => (prev || []).map(bet => {
      if (bet.mode === mode && bet.period === period && bet.status === 'Pending') {
        let win = false;
        let mult = 0;
        if (typeof bet.selection === 'number') { if (bet.selection === winningNum) { win = true; mult = 8.92; } }
        else if (bet.selection === 'Big' || bet.selection === 'Small') { if (bet.selection === result.bigSmall) { win = true; mult = 1.96; } }
        else if (result.colors.includes(bet.selection as ColorType)) {
          win = true; mult = 1.96;
          if ((winningNum === 0 || winningNum === 5) && (bet.selection === ColorType.RED || bet.selection === ColorType.GREEN)) mult = 1.5;
          if (bet.selection === ColorType.VIOLET) mult = 4.41;
        }
        if (win) return { ...bet, status: 'Win', payout: bet.amount * mult };
        return { ...bet, status: 'Loss', payout: 0 };
      }
      return bet;
    }));

    if (totalProfit > 0) {
      setUser(curr => {
        if (!curr) return null;
        const updated = { ...curr, balance: curr.balance + totalProfit };
        setDbUsers(users => (users || []).map(u => u.id === curr.id ? updated : u));
        return updated;
      });
      playSound('win');
    } else if (hadBet) {
      playSound('loss');
    }

    if (activeGame === GameType.WINGO && mode === activeMode && hadBet) {
      setLastResult(result); 
      setLastProfit(totalProfit); 
      setIsResultModalOpen(true);
    }
  }, [activeGame, activeMode, userBets, adminControls, soundEnabled]);

  useEffect(() => {
    const interval = setInterval(() => {
      (Object.keys(MODE_DURATIONS) as GameMode[]).forEach(mode => {
        const { periodId } = getSyncData(mode);
        if (lastProcessedPeriod[mode] && lastProcessedPeriod[mode] !== periodId) {
          processDraw(mode, lastProcessedPeriod[mode]);
        }
        setLastProcessedPeriod(prev => ({ ...prev, [mode]: periodId }));
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lastProcessedPeriod, processDraw]);

  const updateBalance = (amount: number) => {
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance + amount };
      setDbUsers(users => (users || []).map(u => u.id === curr.id ? updated : u));
      return updated;
    });
  };

  const handleBet = (betData: { selection: any, amount: number }) => {
    if (!user) return;
    if (user.balance < betData.amount) {
      alert("Insufficient balance!");
      return;
    }
    playSound('bet');
    const { periodId } = getSyncData(activeMode);
    const newBet: UserBet = {
      id: "BET" + Math.random().toString(36).substr(2, 5).toUpperCase(),
      game: GameType.WINGO,
      period: periodId,
      mode: activeMode,
      amount: betData.amount,
      selection: betData.selection,
      status: 'Pending',
      timestamp: Date.now()
    };
    setUserBets(prev => [newBet, ...(prev || [])]);
    setUser(curr => {
      if (!curr) return null;
      const updated = { ...curr, balance: curr.balance - betData.amount, totalTurnover: curr.totalTurnover + betData.amount };
      setDbUsers(users => (users || []).map(u => u.id === curr.id ? updated : u));
      return updated;
    });
  };

  const handleProcessTx = (id: string, status: 'Completed' | 'Rejected', adminMessage?: string) => {
    setTransactions(prev => (prev || []).map(tx => {
      if (tx.id === id) {
        if (tx.status !== 'Pending') return tx;
        if (tx.type === 'Deposit' && status === 'Completed') {
          setDbUsers(users => (users || []).map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }
        if (tx.type === 'Withdrawal' && status === 'Rejected') {
          setDbUsers(users => (users || []).map(u => {
            if (u.id === tx.userId) {
              const updated = { ...u, balance: u.balance + tx.coins };
              if (user && user.id === u.id) setUser(updated);
              return updated;
            }
            return u;
          }));
        }
        const title = tx.type === 'Withdrawal' ? `Withdrawal ${status}` : `Deposit ${status}`;
        const content = adminMessage ? `Status Update: ${status}\nNote: ${adminMessage}` : `Status Update: ${status}`;
        const newMsg: Message = { id: "MSG" + Date.now(), userId: tx.userId, title, content, timestamp: Date.now(), isRead: false, type: 'Wallet' };
        setMessages(prevMsgs => [newMsg, ...(prevMsgs || [])]);
        return { ...tx, status };
      }
      return tx;
    }));
  };

  const sync = getSyncData(activeMode);
  const unreadCount = user ? (messages || []).filter(m => m.userId === user.id && !m.isRead).length : 0;

  if (!user) return <AuthModal onAuth={(p, pass, reg, ref) => {
    if (reg) {
      const newUser: UserState = { id: "U"+Date.now(), phone: p, password: pass, balance: WELCOME_BONUS, referralCode: ref || "RC"+Math.random(), vipLevel: 1, totalTurnover: 0 };
      setDbUsers(prev => [...(prev || []), newUser]); setUser(newUser);
    } else {
      const u = (dbUsers || []).find(x => x.phone === p && x.password === pass);
      if (u) setUser(u); else alert("Wrong details");
    }
  }} />;

  return (
    <div className="min-h-screen bg-[#11131a] text-white flex justify-center">
      <div className="w-full max-w-md pb-20 relative bg-[#11131a] shadow-2xl overflow-x-hidden">
        {isResultModalOpen && <ResultModal result={lastResult} userProfit={lastProfit} hasBet={true} onClose={() => setIsResultModalOpen(false)} />}

        <header className="sticky top-0 z-40 bg-[#11131a]/95 backdrop-blur-md px-4 py-3 flex justify-between items-center border-b border-white/5">
          <div className="flex items-center gap-2">
            {activeGame && <button onClick={() => { playSound('click'); setActiveGame(null); }} className="mr-2 text-xl active:scale-90 transition-transform">❮</button>}
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center font-black">R</div>
            <div>
              <h1 className="text-lg font-black font-orbitron tracking-tighter">Ritik Club</h1>
              <p className="text-[8px] font-black text-green-500 uppercase tracking-widest">Master Protocol v4.5</p>
            </div>
          </div>
          <div className="text-right flex items-center gap-3">
             <button onClick={() => setSoundEnabled(!soundEnabled)} className="text-lg opacity-40 hover:opacity-100 transition-opacity">
                {soundEnabled ? '🔊' : '🔇'}
             </button>
             <div>
               <p className="text-[10px] text-gray-500 font-black">BALANCE</p>
               <p className="text-sm font-black text-yellow-500 font-orbitron">🪙 {user.balance.toFixed(2)}</p>
             </div>
          </div>
        </header>

        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={(g) => { playSound('click'); setActiveGame(g); }} customGames={customGames || []} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame hasAccess={hasAccess} setTab={setActiveTab} activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode] || []} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.aviator} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, aviator: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.mines} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, mines: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.CRICKET && <CricketGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.cricket} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, cricket: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.VORTEX && <VortexGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.vortex} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, vortex: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.CHICKEN && <ChickenGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.chicken} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, chicken: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.DRAGON_TIGER && <DragonTigerGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.dragonTiger} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, dragonTiger: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.K3 && <K3Game hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.k3} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, k3: null}))} onSound={playSound} />}

          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} onUpdateUser={setUser} onRedeemGift={(code) => {
             const g = (giftCodes || []).find(x => x.code === code);
             if (g) { updateBalance(g.amount); setGiftCodes(prev => (prev || []).filter(x => x.code !== code)); alert("Success!"); playSound('win'); }
          }} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={(transactions || []).filter(t => t.userId === user.id)} onDeposit={(d) => {
             const newTx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Deposit', amount: d.amount, coins: d.amount*10, status: 'Pending', timestamp: Date.now(), utr: d.utr, userUpiId: d.upiId, screenshotUrl: d.screenshot };
             setTransactions(p => [newTx, ...(p || [])]); playSound('bet');
             // Admin notification
             notifyAdmin("New Deposit Request", `User ${user.phone} has requested a deposit of ₹${d.amount}. Please verify UTR: ${d.utr}`);
          }} onWithdraw={(d) => {
             const newTx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Withdrawal', amount: d.amount/10, coins: d.amount, status: 'Pending', timestamp: Date.now(), userUpiId: d.upiId };
             setTransactions(p => [newTx, ...(p || [])]); updateBalance(-d.amount); playSound('click');
             // Admin notification
             notifyAdmin("New Withdrawal Request", `User ${user.phone} has requested a withdrawal of 🪙 ${d.amount} (₹${d.amount/10}). UPI: ${d.upiId}`);
          }} />}
          {activeTab === Tab.INBOX && <InboxView messages={(messages || []).filter(m => m.userId === user.id)} onMarkRead={(id) => setMessages(p => (p || []).map(m => m.id === id ? {...m, isRead: true} : m))} onClearAll={() => setMessages(p => (p || []).filter(m => m.userId !== user.id))} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode] || []} userBets={userBets || []} />}
          {activeTab === Tab.ADMIN && user.phone === ADMIN_PHONE && (
            <AdminView 
              adminControls={adminControls} onUpdateControls={setAdminControls}
              giftCodes={giftCodes || []} onAddGift={(g) => setGiftCodes(p => [...(p || []), g])} onAddGame={(g) => setCustomGames(p => [...(p || []), g])} onRemoveGame={(id) => setCustomGames(p => (p || []).filter(x => x.id !== id))} customGames={customGames || []}
              pendingTxs={(transactions || []).filter(t => t.status === 'Pending')} onProcessTx={handleProcessTx}
            />
          )}
        </main>
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} unreadCount={unreadCount} />
      </div>
    </div>
  );
};

export default App;

export enum ColorType {
  RED = 'RED',
  GREEN = 'GREEN',
  VIOLET = 'VIOLET'
}

export type BigSmallType = 'Big' | 'Small';
export type BetStatus = 'Pending' | 'Win' | 'Loss';
export type TransactionStatus = 'Pending' | 'Completed' | 'Rejected';
export type TransactionType = 'Deposit' | 'Withdrawal';
export type GameMode = '30sec' | '1min' | '3min' | '5min';

export enum GameType {
  WINGO = 'WINGO',
  AVIATOR = 'AVIATOR',
  MINES = 'MINES',
  CHICKEN = 'CHICKEN',
  VORTEX = 'VORTEX',
  CRICKET = 'CRICKET',
  DRAGON_TIGER = 'DRAGON_TIGER',
  K3 = 'K3',
  D5 = 'D5',
  PENALTY = 'PENALTY',
  CUSTOM = 'CUSTOM'
}

export interface GameResult {
  id: string;
  period: string;
  number: number;
  colors: ColorType[];
  bigSmall: BigSmallType;
  timestamp: number;
}

export interface UserBet {
  id: string;
  game?: GameType;
  period: string;
  mode: GameMode | string;
  amount: number;
  selection: ColorType | number | BigSmallType | string;
  status: BetStatus;
  payout?: number;
  timestamp: number;
}

export interface Transaction {
  id: string;
  userId: string;
  type: TransactionType;
  amount: number;
  coins: number;
  status: TransactionStatus;
  timestamp: number;
  utr?: string;
  userUpiId?: string;
  screenshotUrl?: string;
}

export interface Message {
  id: string;
  userId: string;
  title: string;
  content: string;
  timestamp: number;
  isRead: boolean;
  type: 'System' | 'Wallet' | 'Promo';
}

export interface UserState {
  id: string;
  phone: string;
  password?: string;
  balance: number;
  referralCode: string;
  avatarUrl?: string;
  vipLevel: number;
  totalTurnover: number;
}

export interface GiftCode {
  code: string;
  amount: number;
}

export interface CustomGame {
  id: string;
  name: string;
  url: string;
  icon: string;
  color: string;
}

export enum Tab {
  HOME = 'HOME',
  HISTORY = 'HISTORY',
  WALLET = 'WALLET',
  INBOX = 'INBOX',
  PROFILE = 'PROFILE',
  SUPPORT = 'SUPPORT',
  ADMIN = 'ADMIN'
}

export type ImageSize = '1K' | '2K' | '4K';

import React from 'react';
import { GameType, UserState, CustomGame } from '../types.ts';

interface HomeViewProps {
  user: UserState;
  onSelectGame: (game: GameType) => void;
  customGames: CustomGame[];
}

const HomeView: React.FC<HomeViewProps> = ({ user, onSelectGame, customGames }) => {
  const categories = ["All Games", "Lottery", "Crash", "Casino", "Sports"];

  const defaultGames = [
    { id: GameType.WINGO, name: 'Win Go', icon: '🎰', color: 'from-blue-600 to-indigo-600', sub: '8.92x Multiplier' },
    { id: GameType.AVIATOR, name: 'Aviator', icon: '✈️', color: 'from-red-600 to-rose-700', sub: 'Instant Cashout' },
    { id: GameType.D5, name: '5D Lotre', icon: '🔢', color: 'from-cyan-600 to-blue-700', sub: '5-Digit Fortune' },
    { id: GameType.PENALTY, name: 'Penalty', icon: '⚽', color: 'from-emerald-500 to-green-700', sub: 'Goal Rush' },
    { id: GameType.MINES, name: 'Mines', icon: '💣', color: 'from-yellow-600 to-amber-700', sub: 'Minefield Rush' },
    { id: GameType.K3, name: 'K3 Dice', icon: '🎲', color: 'from-purple-600 to-pink-700', sub: 'Triple Sum' },
    { id: GameType.DRAGON_TIGER, name: 'Dragon Tiger', icon: '🐉', color: 'from-orange-600 to-red-700', sub: 'Card Battle' },
    { id: GameType.CRICKET, name: 'Cricket', icon: '🏏', color: 'from-green-600 to-emerald-700', sub: 'Ball by Ball' },
    { id: GameType.VORTEX, name: 'Vortex', icon: '🌀', color: 'from-indigo-600 to-blue-800', sub: 'Shift Luck' },
    { id: GameType.CHICKEN, name: 'Chicken', icon: '🍗', color: 'from-amber-500 to-orange-700', sub: 'Path Finder' },
  ];

  const handleCustomGame = (url: string) => {
    window.open(url, '_blank');
  };

  return (
    <div className="space-y-6 px-4 py-4 animate-in fade-in slide-in-from-bottom duration-500">
      <div className="h-44 rounded-3xl bg-gradient-to-r from-blue-900 via-indigo-900 to-purple-900 p-6 flex flex-col justify-center relative overflow-hidden border border-white/10 shadow-2xl">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/10 blur-[100px] -mr-32 -mt-32"></div>
        <h2 className="text-2xl font-black font-orbitron mb-2 relative z-10 leading-tight text-yellow-500 uppercase">New User Reward<br/>🪙 25 Coins</h2>
        <p className="text-[10px] font-black text-white/50 uppercase tracking-[0.3em] relative z-10">Smart House House Advantage: ON</p>
        <div className="mt-4 flex gap-2 relative z-10">
           <span className="bg-white/10 px-3 py-1 rounded-full text-[8px] font-black border border-white/5">Verified Security</span>
           <span className="bg-white/10 px-3 py-1 rounded-full text-[8px] font-black border border-white/5">Fair Play System</span>
        </div>
      </div>

      <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
        {categories.map((c, i) => (
          <button key={i} className={`px-5 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest whitespace-nowrap border ${i === 0 ? 'bg-blue-600 border-blue-400 shadow-lg' : 'bg-[#1e2330] border-white/5 text-gray-500'}`}>
            {c}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-2 gap-4">
        {defaultGames.map((g) => (
          <button 
            key={g.id}
            onClick={() => onSelectGame(g.id)}
            className={`bg-gradient-to-br ${g.color} p-4 rounded-3xl text-left border border-white/10 shadow-xl active:scale-95 transition-all group relative overflow-hidden h-36 flex flex-col justify-end`}
          >
            <div className="absolute top-4 right-4 text-3xl opacity-50 transition-transform group-hover:scale-125 duration-500">{g.icon}</div>
            <div className="relative z-10">
              <p className="text-xs font-black font-orbitron uppercase leading-none">{g.name}</p>
              <p className="text-[7px] font-bold text-white/60 uppercase mt-1 tracking-widest">{g.sub}</p>
            </div>
