        <main>
          {activeTab === Tab.HOME && !activeGame && <HomeView user={user} onSelectGame={(g) => { playSound('click'); setActiveGame(g); }} customGames={customGames || []} />}
          {activeTab === Tab.HOME && activeGame === GameType.WINGO && <WinGoGame hasAccess={hasAccess} setTab={setActiveTab} activeMode={activeMode} setActiveMode={setActiveMode} timeLeft={sync.timeLeft} period={sync.periodId} results={results[activeMode] || []} balance={user.balance} onBet={handleBet} />}
          {activeTab === Tab.HOME && activeGame === GameType.AVIATOR && <AviatorGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.aviator} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, aviator: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.MINES && <MinesGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.mines} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, mines: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.D5 && <D5Game hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.d5} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, d5: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.PENALTY && <PenaltyGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} onUpdateBalance={updateBalance} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.CRICKET && <CricketGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.cricket} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, cricket: null}))} />}
          {activeTab === Tab.HOME && activeGame === GameType.VORTEX && <VortexGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.vortex} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, vortex: null}))} />}
          {activeTab === Tab.HOME && activeGame === GameType.CHICKEN && <ChickenGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.chicken} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, chicken: null}))} />}
          {activeTab === Tab.HOME && activeGame === GameType.DRAGON_TIGER && <DragonTigerGame hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.dragonTiger} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, dragonTiger: null}))} onSound={playSound} />}
          {activeTab === Tab.HOME && activeGame === GameType.K3 && <K3Game hasAccess={hasAccess} setTab={setActiveTab} balance={user.balance} adminOverride={adminControls.k3} onUpdateBalance={updateBalance} onClearOverride={() => setAdminControls(p => ({...p, k3: null}))} />}
          {activeTab === Tab.PROFILE && <ProfileView user={user} setTab={setActiveTab} onUpdateUser={setUser} onRedeemGift={(code) => { const g = (giftCodes || []).find(x => x.code === code); if (g) { updateBalance(g.amount); setGiftCodes(prev => (prev || []).filter(x => x.code !== code)); alert("Success!"); playSound('win'); } }} />}
          {activeTab === Tab.WALLET && <WalletView balance={user.balance} transactions={(transactions || []).filter(t => t.userId === user.id)} onDeposit={(d) => { const newTx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Deposit', amount: d.amount, coins: d.amount*10, status: 'Pending', timestamp: Date.now(), utr: d.utr, userUpiId: d.upiId, screenshotUrl: d.screenshot }; setTransactions(p => [newTx, ...(p || [])]); playSound('bet'); notifyAdmin("New Deposit Request", `User ${user.phone} has requested a deposit of ₹${d.amount}. Please verify UTR: ${d.utr}`); }} onWithdraw={(d) => { const newTx: Transaction = { id: "TX"+Date.now(), userId: user.id, type: 'Withdrawal', amount: d.amount/10, coins: d.amount, status: 'Pending', timestamp: Date.now(), userUpiId: d.upiId }; setTransactions(p => [newTx, ...(p || [])]); updateBalance(-d.amount); playSound('click'); notifyAdmin("New Withdrawal Request", `User ${user.phone} has requested a withdrawal of 🪙 ${d.amount} (₹${d.amount/10}). UPI: ${d.upiId}`); }} />}
          {activeTab === Tab.INBOX && <InboxView messages={(messages || []).filter(m => m.userId === user.id)} onMarkRead={(id) => setMessages(p => (p || []).map(m => m.id === id ? {...m, isRead: true} : m))} onClearAll={() => setMessages(p => (p || []).filter(m => m.userId !== user.id))} />}
          {activeTab === Tab.HISTORY && <HistoryView results={results[activeMode] || []} userBets={userBets || []} />}
          {activeTab === Tab.ADMIN && user.phone === ADMIN_PHONE && (
            <AdminView 
              adminControls={adminControls} onUpdateControls={setAdminControls}
              giftCodes={giftCodes || []} onAddGift={(g) => setGiftCodes(p => [...(p || []), g])} onAddGame={(g) => setCustomGames(p => [...(p || []), g])} onRemoveGame={(id) => setCustomGames(p => (p || []).filter(x => x.id !== id))} customGames={customGames || []}
              pendingTxs={(transactions || []).filter(t => t.status === 'Pending')} onProcessTx={handleProcessTx}
            />
          )}
        </main>
        <Navigation activeTab={activeTab} setActiveTab={setActiveTab} userPhone={user.phone} unreadCount={unreadCount} />
      </div>
    </div>
  );
};

export default App;

