import React, { useState, useEffect } from 'react';
import { Tab } from '../types.ts';

interface ChickenGameProps {
  balance: number;
  onUpdateBalance: (a: number) => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  adminOverride: number | null; // Max safe lane
  onClearOverride: () => void;
}

const ChickenGame: React.FC<ChickenGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab, adminOverride, onClearOverride }) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentLane, setCurrentLane] = useState(4); // 4 is bottom, 0 is top
  const [gameOver, setGameOver] = useState(false);
  const [won, setWon] = useState(false);

  // Lane multipliers
  const multipliers = [12.0, 5.5, 3.0, 1.8, 1.2];

  const startGame = () => {
    if (!hasAccess || balance < bet) return;
    onUpdateBalance(-bet);
    setIsPlaying(true);
    setGameOver(false);
    setWon(false);
    setCurrentLane(4);
  };

  const attemptCross = () => {
    if (!isPlaying || gameOver || won) return;

    let isSafe: boolean;
    const laneIndexFromBottom = 4 - currentLane; // currentLane goes 4 to 0

    if (adminOverride !== null) {
      isSafe = laneIndexFromBottom < adminOverride;
      // If we crossed the max safe lane, clear the override
      if (!isSafe) onClearOverride();
    } else {
      // Natural difficulty: 70% chance to pass each lane
      isSafe = Math.random() < 0.7;
    }

    if (isSafe) {
      if (currentLane === 0) {
        setWon(true);
        setIsPlaying(false);
        onUpdateBalance(bet * multipliers[0]);
      } else {
        setCurrentLane(prev => prev - 1);
      }
    } else {
      setGameOver(true);
      setIsPlaying(false);
    }
  };

  const cashOut = () => {
    if (!isPlaying || currentLane === 4) return;
    const currentMultiplier = multipliers[currentLane + 1] || 1;
    onUpdateBalance(bet * currentMultiplier);
    setIsPlaying(false);
    setWon(true);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-700">
      <div className="relative h-96 bg-[#0a0c10] rounded-[2.5rem] border border-white/5 overflow-hidden shadow-2xl flex flex-col p-2">
        {/* The Road Lanes */}
        {[0, 1, 2, 3, 4].map(lane => (
          <div key={lane} className={`flex-1 border-b border-white/5 relative flex items-center justify-center transition-all ${currentLane === lane ? 'bg-blue-600/10' : ''}`}>
             <div className="absolute left-0 right-0 h-[1px] bg-white/5 top-1/2 -translate-y-1/2 border-t border-dashed"></div>
             {currentLane === lane && (
                <div className="text-4xl animate-bounce z-10">🐥</div>
             )}
             {/* Hazards (Visual only for now) */}
             <div className="absolute animate-car-move whitespace-nowrap opacity-20 text-xl">
               🏎️ ... 🚐 ... 🚗
             </div>
             <div className="absolute right-4 text-[8px] font-black text-white/10 uppercase">{multipliers[lane]}x</div>
          </div>
        ))}

        {gameOver && (
           <div className="absolute inset-0 bg-red-950/80 backdrop-blur-md flex flex-col items-center justify-center z-20 animate-in zoom-in">
              <p className="text-4xl font-black font-orbitron text-red-500 animate-shake">CRASHED!</p>
              <button onClick={startGame} className="mt-6 bg-white/10 px-8 py-3 rounded-full text-xs font-black uppercase">Try Again</button>
           </div>
        )}

        {won && (
           <div className="absolute inset-0 bg-green-950/80 backdrop-blur-md flex flex-col items-center justify-center z-20 animate-in zoom-in">
              <p className="text-4xl font-black font-orbitron text-green-500 win-glow">GOAL!</p>
              <button onClick={() => setWon(false)} className="mt-6 bg-white/10 px-8 py-3 rounded-full text-xs font-black uppercase">Continue</button>
           </div>
        )}
      </div>

      <div className="bg-[#1e2330] rounded-[2.5rem] p-6 border border-white/5 space-y-4">
        {!hasAccess ? (
           <button onClick={() => setTab(Tab.WALLET)} className="w-full py-4 bg-orange-600 rounded-2xl font-black text-[10px] uppercase tracking-widest">Deposit ₹20 for Road 2</button>
        ) : (
           <>
              <div className="flex justify-between items-center mb-4">
                 <div className="text-left">
                    <p className="text-[9px] text-gray-500 uppercase font-black">Multiplier</p>
                    <p className="text-2xl font-black font-orbitron text-yellow-500">{multipliers[currentLane] || '1.0'}x</p>
                 </div>
                 <div className="text-right">
                    <p className="text-[9px] text-gray-500 uppercase font-black">Bet</p>
                    <p className="text-lg font-black font-orbitron">🪙 {bet}</p>
                 </div>
              </div>

              {isPlaying ? (
                <div className="flex gap-2">
                   <button onClick={attemptCross} className="flex-[2] py-5 bg-blue-600 rounded-2xl font-black text-lg uppercase shadow-2xl active:scale-95 transition-all">Advance 🐥</button>
                   <button onClick={cashOut} disabled={currentLane === 4} className="flex-1 py-5 bg-green-600/20 text-green-500 rounded-2xl font-black text-xs uppercase border border-green-500/20">Take Win</button>
                </div>
              ) : (
                <div className="space-y-4">
                   <div className="flex gap-2">
                      {[10, 50, 100].map(amt => (
                        <button key={amt} onClick={() => setBet(amt)} className={`flex-1 py-3 rounded-xl font-black text-[10px] border transition-all ${bet === amt ? 'bg-orange-600 border-white' : 'bg-white/5 border-white/5 text-gray-500'}`}>{amt}</button>
                      ))}
                   </div>
                   <button onClick={startGame} className="w-full py-5 bg-orange-600 text-white rounded-3xl font-black text-lg uppercase shadow-2xl active:scale-95 transition-all">Start Crossing</button>
                </div>
              )}
           </>
        )}
      </div>

      <style>{`
        @keyframes car-move {
          from { transform: translateX(-100%); }
          to { transform: translateX(400%); }
        }
        .animate-car-move {
          animation: car-move 5s linear infinite;
        }
      `}</style>
    </div>
  );
};

