import React, { useState } from 'react';
import { Tab } from '../types.ts';

interface PlinkoGameProps {
  balance: number;
  onUpdateBalance: (a: number) => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  onSound: (k: any) => void;
  adminOverride: number | null;
  onClearOverride: () => void;
}

const PlinkoGame: React.FC<PlinkoGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab, onSound, adminOverride, onClearOverride }) => {
  const [bet, setBet] = useState(10);
  const [isDropping, setIsDropping] = useState(false);
  const [ballPath, setBallPath] = useState<number[]>([]);
  const [result, setResult] = useState<number | null>(null);

  const multipliers = [50, 20, 10, 5, 2, 0.5, 0.2, 0.5, 2, 5, 10, 20, 50];

  const handleDrop = () => {
    if (!hasAccess || isDropping || balance < bet) return;
    onSound('bet');
    onUpdateBalance(-bet);
    setIsDropping(true);
    setResult(null);

    let path = [];
    let currentPos = 6; // start at center of 13 slots

    // 8 rows of pins
    for(let i=0; i<8; i++) {
      path.push(currentPos);
      currentPos += Math.random() > 0.5 ? 0.5 : -0.5;
    }

    // Final bucket
    let finalBucket: number;
    if (adminOverride !== null) {
      finalBucket = adminOverride;
      onClearOverride();
    } else {
      finalBucket = Math.floor(Math.random() * multipliers.length);
    }

    setTimeout(() => {
      const win = bet * multipliers[finalBucket];
      onUpdateBalance(win);
      setResult(multipliers[finalBucket]);
      setIsDropping(false);
      onSound(win > bet ? 'win' : 'loss');
    }, 1500);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <div className="h-96 bg-[#0a0c10] rounded-[2.5rem] relative overflow-hidden border border-white/10 shadow-2xl flex flex-col items-center p-4">
        {/* Peg Board Simulation */}
        <div className="flex-1 w-full flex flex-col items-center justify-center gap-4 relative">
           <div className={`w-6 h-6 bg-pink-500 rounded-full shadow-[0_0_15px_rgba(236,72,153,0.5)] ${isDropping ? 'animate-bounce' : ''}`}></div>

           <div className="grid grid-cols-13 gap-1 w-full mt-auto">
              {multipliers.map((m, i) => (
                <div key={i} className={`h-12 flex flex-col items-center justify-center rounded-lg text-[8px] font-black border border-white/5 ${m >= 10 ? 'bg-pink-600/20 text-pink-400' : 'bg-white/5 text-gray-500'}`}>
                   <span>{m}x</span>
                   <div className="w-full h-1 bg-white/10 mt-1"></div>
                </div>
              ))}
           </div>
        </div>

        {result !== null && (
          <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center z-20 animate-in zoom-in">
             <p className={`text-5xl font-black font-orbitron ${result >= 1 ? 'text-pink-500' : 'text-gray-500'}`}>{result}x</p>
             <p className="text-[10px] font-black text-white mt-2">WIN: 🪙 {(bet * result).toFixed(1)}</p>
             <button onClick={() => setResult(null)} className="mt-6 bg-white/10 px-8 py-2 rounded-full text-[10px] font-black uppercase">Play Again</button>
          </div>
        )}
      </div>

      <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-4">
        {!hasAccess ? (
           <button onClick={() => setTab(Tab.WALLET)} className="w-full py-4 bg-pink-600 rounded-2xl font-black text-[10px] uppercase">Deposit ₹20 for Plinko</button>
        ) : (
           <>
              <div className="flex justify-between items-center bg-black/20 p-4 rounded-2xl">
                <button onClick={() => { onSound('click'); setBet(Math.max(10, bet-10)); }} className="w-10 h-10 bg-white/5 rounded-xl font-black active:scale-75">-</button>
                <div className="text-center"><p className="text-[8px] text-gray-600 font-black">BET</p><p className="text-lg font-black font-orbitron text-pink-500">🪙 {bet}</p></div>
                <button onClick={() => { onSound('click'); setBet(bet+10); }} className="w-10 h-10 bg-white/5 rounded-xl font-black active:scale-75">+</button>
              </div>
              <button onClick={handleDrop} disabled={isDropping} className={`w-full py-5 rounded-3xl font-black text-lg uppercase shadow-2xl transition-all ${isDropping ? 'bg-gray-800' : 'bg-pink-600'}`}>Drop Ball</button>
           </>
        )}
      </div>
      <style>{`
        .grid-cols-13 { grid-template-columns: repeat(13, minmax(0, 1fr)); }
      `}</style>
    </div>
  );
};

