import React, { useState } from 'react';
import { Tab } from '../types.ts';

interface WheelGameProps {
  balance: number;
  onUpdateBalance: (a: number) => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  onSound: (k: any) => void;
  adminOverride: number | null;
  onClearOverride: () => void;
}

const WheelGame: React.FC<WheelGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab, onSound, adminOverride, onClearOverride }) => {
  const [bet, setBet] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const [result, setResult] = useState<number | null>(null);

  const segments = [1.2, 2, 0.5, 5, 1.5, 0.2, 10, 0.8]; // 8 segments

  const handleSpin = () => {
    if (!hasAccess || isSpinning || balance < bet) return;
    onSound('bet');
    onUpdateBalance(-bet);
    setIsSpinning(true);
    setResult(null);

    let targetIdx: number;
    if (adminOverride !== null) {
      targetIdx = adminOverride;
      onClearOverride();
    } else {
      targetIdx = Math.floor(Math.random() * segments.length);
    }

    const newRotation = rotation + (360 * 5) + (targetIdx * 45);
    setRotation(newRotation);

    setTimeout(() => {
      const win = bet * segments[targetIdx];
      onUpdateBalance(win);
      setResult(segments[targetIdx]);
      setIsSpinning(false);
      onSound(win > bet ? 'win' : 'loss');
    }, 4000);
  };

  return (
    <div className="p-4 space-y-6 animate-in fade-in duration-500">
      <div className="h-80 bg-[#0a0c10] rounded-[2.5rem] relative overflow-hidden border border-white/10 shadow-2xl flex items-center justify-center">
        {/* Wheel UI */}
        <div className="relative w-64 h-64">
           <div className="absolute top-0 left-1/2 -translate-x-1/2 w-6 h-8 bg-white rounded-full shadow-lg z-20 -mt-2"></div>
           <div 
             className="w-full h-full rounded-full border-8 border-white/5 transition-all duration-[4s] ease-out relative"
             style={{ transform: `rotate(${rotation}deg)`, background: 'conic-gradient(#3b82f6 0deg 45deg, #1e293b 45deg 90deg, #3b82f6 90deg 135deg, #1e293b 135deg 180deg, #ef4444 180deg 225deg, #1e293b 225deg 270deg, #eab308 270deg 315deg, #1e293b 315deg 360deg)' }}
           >
              {segments.map((s, i) => (
                <div key={i} className="absolute top-0 left-1/2 -translate-x-1/2 h-1/2 pt-4 origin-bottom font-black text-[10px]" style={{ transform: `rotate(${i * 45 + 22.5}deg)` }}>
                   {s}x
                </div>
              ))}
           </div>
        </div>

        {result !== null && (
          <div className="absolute inset-0 bg-black/70 flex flex-col items-center justify-center z-30 animate-in zoom-in">
             <p className="text-5xl font-black font-orbitron text-yellow-500">{result}x</p>
             <p className="text-sm font-black text-white mt-2">Payout: 🪙 {(bet * result).toFixed(1)}</p>
             <button onClick={() => setResult(null)} className="mt-6 bg-white/10 px-8 py-2 rounded-full text-[10px] font-black uppercase">Spin Again</button>
          </div>
        )}
      </div>

      <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-4">
        {!hasAccess ? (
