import React, { useState, useEffect, useRef } from 'react';
import { Tab, GameType } from '../types.ts';

interface AviatorGameProps {
  balance: number;
  adminOverride: number | null;
  onUpdateBalance: (amount: number) => void;
  onClearOverride: () => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  onSound: (k: any) => void;
  userBets: any[];
}

const AviatorGame: React.FC<AviatorGameProps> = ({ balance, adminOverride, onUpdateBalance, onClearOverride, hasAccess, setTab, onSound, userBets }) => {
  const [multiplier, setMultiplier] = useState(1.00);
  const [isFlying, setIsFlying] = useState(false);
  const [isCrashed, setIsCrashed] = useState(false);
  const [crashPoint, setCrashPoint] = useState(1.00);
  const [bet1, setBet1] = useState({ amount: 10, active: false, cashed: false });
  const [bet2, setBet2] = useState({ amount: 10, active: false, cashed: false });
  const [history, setHistory] = useState([1.08, 1.00, 4.90, 1.23, 2.31, 1.71]);

  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 25000;
      const cycleTime = now % periodDuration;
      const waitTime = 8000;

      if (cycleTime < waitTime) {
        setIsFlying(false);
        setIsCrashed(false);
        setMultiplier(1.00);
        if (cycleTime < 500) {
           setBet1(p => ({ ...p, active: false, cashed: false }));
           setBet2(p => ({ ...p, active: false, cashed: false }));
        }
      } else {
        if (!isFlying) {
          const target = adminOverride || (1 + Math.random() * 5);
          setCrashPoint(target);
          setIsFlying(true);
          onClearOverride();
        }
        const elapsed = (cycleTime - waitTime) / 1000;
        const currentMult = Math.pow(1.12, elapsed);
        if (currentMult >= crashPoint) {
          if (!isCrashed) {
             onSound('crash');
             setHistory(prev => [crashPoint, ...prev].slice(0, 10));
          }
          setIsCrashed(true);
          setMultiplier(crashPoint);
        } else {
          setMultiplier(currentMult);
        }
      }
    }, 50);
    return () => clearInterval(interval);
  }, [isFlying, adminOverride, crashPoint]);

  // Canvas Flight Animation
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    const render = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      if (isFlying && !isCrashed) {
        ctx.beginPath();
        ctx.strokeStyle = '#e11d48';
        ctx.lineWidth = 4;
        ctx.moveTo(0, canvas.height);
        const x = (multiplier - 1) * 100;
        const y = canvas.height - Math.pow(multiplier, 1.5) * 10;
        ctx.quadraticCurveTo(x / 2, canvas.height, x, y);
        ctx.stroke();
        // Plane Icon
        ctx.font = '30px serif';
        ctx.fillText('✈️', x - 15, y + 10);
      }
      animationFrameId = requestAnimationFrame(render);
    };
    render();
    return () => cancelAnimationFrame(animationFrameId);
  }, [multiplier, isFlying, isCrashed]);

  const handleBet = (panel: 1 | 2) => {
    const bet = panel === 1 ? bet1 : bet2;
    if (balance < bet.amount) return;
    onUpdateBalance(-bet.amount);
    if (panel === 1) setBet1({ ...bet1, active: true });
    else setBet2({ ...bet2, active: true });
    onSound('bet');
  };

  const handleCashout = (panel: 1 | 2) => {
    const bet = panel === 1 ? bet1 : bet2;
    if (!isFlying || isCrashed || !bet.active || bet.cashed) return;
    const win = bet.amount * multiplier;
    onUpdateBalance(win);
    if (panel === 1) setBet1({ ...bet1, cashed: true });
    else setBet2({ ...bet2, cashed: true });
    onSound('win');
  };

  const myGameBets = userBets.filter(b => b.game === GameType.AVIATOR).slice(0, 5);

  return (
    <div className="flex flex-col h-full bg-[#11131a] overflow-y-auto no-scrollbar pb-24">
      {/* Top History Bar */}
      <div className="flex gap-2 p-2 bg-black/40 overflow-x-auto no-scrollbar border-b border-white/5">
        {history.map((h, i) => (
          <span key={i} className={`px-3 py-1 rounded-full text-[9px] font-black border ${h > 2 ? 'text-purple-400 border-purple-500/30' : 'text-blue-400 border-blue-500/30'}`}>{h.toFixed(2)}x</span>
        ))}
      </div>

      {/* Main Flight Area */}
      <div className="relative h-72 bg-[#0a0c10] m-2 rounded-3xl border border-white/5 overflow-hidden flex flex-col items-center justify-center">
         <canvas ref={canvasRef} width={400} height={300} className="absolute inset-0 w-full h-full" />
         <div className="z-10 text-center">
            {isCrashed ? (
              <p className="text-5xl font-black font-orbitron text-red-600 drop-shadow-lg">FLEW AWAY!</p>
            ) : (
              <p className="text-7xl font-black font-orbitron text-white">{multiplier.toFixed(2)}x</p>
            )}
         </div>
      </div>

      {/* Dual Betting Panels */}
      <div className="grid grid-cols-1 gap-4 p-2">
         {[1, 2].map((p: any) => {
           const b = p === 1 ? bet1 : bet2;
           const sB = p === 1 ? setBet1 : setBet2;
           return (
             <div key={p} className="bg-[#1e2330] p-4 rounded-3xl border border-white/5 flex gap-4 items-center">
                <div className="flex-1 space-y-2">
                   <div className="flex items-center justify-between bg-black/40 rounded-xl px-4 py-2">
                      <button onClick={() => sB({...b, amount: Math.max(1, b.amount-10)})} className="text-xl font-black">-</button>
                      <span className="font-orbitron font-black text-sm">{b.amount}.00</span>
                      <button onClick={() => sB({...b, amount: b.amount+10})} className="text-xl font-black">+</button>
                   </div>
                   <div className="grid grid-cols-2 gap-2">
                      {[10, 100].map(v => <button key={v} onClick={() => sB({...b, amount: v})} className="bg-white/5 py-1 rounded-lg text-[10px] font-black">{v}</button>)}
                   </div>
                </div>
                {!b.active ? (
                  <button onClick={() => handleBet(p)} className="flex-1 h-full bg-green-600 rounded-2xl font-black text-xl uppercase py-4 shadow-lg shadow-green-900/20">BET</button>
                ) : (
                  <button onClick={() => handleCashout(p)} disabled={isCrashed || b.cashed} className={`flex-1 h-full rounded-2xl font-black text-sm uppercase py-4 ${b.cashed ? 'bg-blue-600' : isCrashed ? 'bg-gray-800' : 'bg-orange-500'}`}>
                    {b.cashed ? 'CASHED' : isCrashed ? 'CRASHED' : `OUT ${(b.amount * multiplier).toFixed(1)}`}
                  </button>
                )}
             </div>
           );
         })}
      </div>

      {/* Game History Section Below Game */}
      <div className="p-4 space-y-4">
         <h3 className="text-xs font-black font-orbitron text-gray-500 uppercase tracking-widest">Recent Activity</h3>
         <div className="bg-[#1e2330] rounded-2xl overflow-hidden border border-white/5">
            {myGameBets.map(bet => (
              <div key={bet.id} className="p-4 border-b border-white/5 flex justify-between items-center text-[10px]">
                 <div><p className="font-black text-white">{bet.id}</p><p className="text-gray-500 font-bold uppercase">{new Date(bet.timestamp).toLocaleTimeString()}</p></div>
                 <div className="text-right">
                    <p className="font-black">🪙 {bet.amount}</p>
                    <p className={bet.status === 'Win' ? 'text-green-500' : 'text-red-500'}>{bet.status}</p>
                 </div>
              </div>
            ))}
            {myGameBets.length === 0 && <p className="p-10 text-center text-[10px] text-gray-600 font-black uppercase">No local bets found</p>}
         </div>
      </div>
    </div>
  );
};

