import React, { useState } from 'react';
import { Tab, GameType } from '../types.ts';

interface ChickenGameProps {
  balance: number;
  onUpdateBalance: (a: number) => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  adminOverride: number | null;
  onClearOverride: () => void;
  userBets: any[];
}

const ChickenGame: React.FC<ChickenGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab, adminOverride, onClearOverride, userBets }) => {
  const [bet, setBet] = useState(1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentLane, setCurrentLane] = useState(-1); // -1 = sidewalk
  const [gameOver, setGameOver] = useState(false);
  const [won, setWon] = useState(false);

  const multipliers = [1.45, 2.10, 3.50, 6.80, 12.0];

  const handlePlay = () => {
    if (balance < bet || isPlaying) return;
    onUpdateBalance(-bet);
    setIsPlaying(true);
    setGameOver(false);
    setWon(false);
    setCurrentLane(-1);
  };

  const step = (idx: number) => {
    if (!isPlaying || idx !== currentLane + 1) return;

    let safe = adminOverride === null ? Math.random() > 0.3 : idx < adminOverride;
    if (adminOverride !== null && idx >= adminOverride) onClearOverride();

    if (safe) {
      setCurrentLane(idx);
      if (idx === multipliers.length - 1) {
        onUpdateBalance(bet * multipliers[idx]);
        setWon(true);
        setIsPlaying(false);
      }
    } else {
      setGameOver(true);
      setIsPlaying(false);
    }
  };

  const cashout = () => {
    if (!isPlaying || currentLane < 0) return;
    onUpdateBalance(bet * multipliers[currentLane]);
    setWon(true);
    setIsPlaying(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#11131a] overflow-y-auto no-scrollbar pb-24">
      {/* Street View Area */}
