            <p className="text-center text-[8px] font-black text-gray-500 uppercase tracking-[0.4em]">Official Game</p>
         </div>

         {/* Concentric Rings Board */}
         <div className="relative w-72 h-72 rounded-full border-8 border-[#1e2330] shadow-2xl flex items-center justify-center">
