import React, { useState } from 'react';
import { Tab, GameType } from '../types.ts';

interface WheelGameProps {
  balance: number;
  onUpdateBalance: (a: number) => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  onSound: (k: any) => void;
  adminOverride: number | null;
  onClearOverride: () => void;
  userBets: any[];
}

const WheelGame: React.FC<WheelGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab, onSound, adminOverride, onClearOverride, userBets }) => {
  const [bet, setBet] = useState(10);
  const [isSpinning, setIsSpinning] = useState(false);
  const [rotation, setRotation] = useState(0);
  const [result, setResult] = useState<number | null>(null);

  // Increased 0x segments for higher loss probability
  const segments = [0, 0, 2, 0, 0, 5, 0, 10]; 

  const handleSpin = () => {
    if (!hasAccess || isSpinning || balance < bet) return;
    onSound('bet');
    onUpdateBalance(-bet);
    setIsSpinning(true);
    setResult(null);

    let targetIdx = adminOverride !== null ? adminOverride : Math.floor(Math.random() * segments.length);
    const newRotation = rotation + (360 * 5) + (targetIdx * 45);
    setRotation(newRotation);
    if (adminOverride !== null) onClearOverride();

    setTimeout(() => {
      const win = bet * segments[targetIdx];
      onUpdateBalance(win);
      setResult(segments[targetIdx]);
      setIsSpinning(false);
      onSound(win > bet ? 'win' : 'loss');
    }, 4000);
  };

  const myGameBets = userBets.filter(b => b.game === GameType.WHEEL).slice(0, 5);

  return (
    <div className="flex flex-col h-full bg-[#11131a] overflow-y-auto no-scrollbar pb-24">
      <div className="h-80 bg-[#0a0c10] m-2 rounded-[2.5rem] relative overflow-hidden border border-white/10 shadow-2xl flex items-center justify-center">
        <div className="relative w-64 h-64">
           <div className="absolute top-0 left-1/2 -translate-x-1/2 w-6 h-8 bg-white rounded-full shadow-lg z-20 -mt-2"></div>
           <div 
             className="w-full h-full rounded-full border-8 border-white/5 transition-all duration-[4s] ease-out relative"
             style={{ transform: `rotate(${rotation}deg)`, background: 'conic-gradient(#3b82f6 0deg 45deg, #1e293b 45deg 90deg, #3b82f6 90deg 135deg, #1e293b 135deg 180deg, #ef4444 180deg 225deg, #1e293b 225deg 270deg, #eab308 270deg 315deg, #1e293b 315deg 360deg)' }}
           >
              {segments.map((s, i) => (
                <div key={i} className={`absolute top-0 left-1/2 -translate-x-1/2 h-1/2 pt-4 origin-bottom font-black text-[10px] ${s === 0 ? 'text-red-500 animate-pulse' : 'text-white'}`} style={{ transform: `rotate(${i * 45 + 22.5}deg)` }}>
                   {s === 0 ? '0x' : s+'x'}
                </div>
              ))}
           </div>
        </div>
      </div>

      <div className="p-4 bg-[#1e2330] m-2 rounded-3xl space-y-4 shadow-xl border border-white/5">
         <div className="flex justify-between items-center bg-black/40 p-4 rounded-2xl">
            <button onClick={() => setBet(Math.max(1, bet-10))} className="w-10 h-10 bg-white/5 rounded-xl font-black active:scale-90 transition-transform">－</button>
            <span className="text-xl font-orbitron font-black text-yellow-500">🪙 {bet}</span>
            <button onClick={() => setBet(bet+10)} className="w-10 h-10 bg-white/5 rounded-xl font-black active:scale-90 transition-transform">＋</button>
         </div>
         <button onClick={handleSpin} disabled={isSpinning} className="w-full py-5 bg-gradient-to-r from-blue-600 to-indigo-700 rounded-3xl font-black uppercase text-lg shadow-xl shadow-blue-900/20 active:scale-95 transition-all">Spin Wheel</button>
      </div>

      {/* Embedded History Section */}
      <div className="p-4 space-y-3">
         <h3 className="text-xs font-black font-orbitron text-gray-600 uppercase tracking-widest px-2">Draw Ledger</h3>
         <div className="bg-[#1e2330] rounded-2xl overflow-hidden border border-white/5">
            {myGameBets.map(b => (
              <div key={b.id} className="p-4 border-b border-white/5 flex justify-between items-center text-[10px] font-black">
                 <div><p className="text-gray-400">{b.id}</p><p className="text-[8px] text-gray-600 uppercase">{new Date(b.timestamp).toLocaleTimeString()}</p></div>
                 <div className="text-right">
                    <p className={b.status === 'Win' ? 'text-green-500' : 'text-red-500'}>{b.status} ({b.payout} INR)</p>
                 </div>
              </div>
            ))}
            {myGameBets.length === 0 && <p className="p-10 text-center text-[9px] text-gray-700 uppercase font-black">No rounds found</p>}
         </div>
      </div>
    </div>
  );
};

