import React, { useState } from 'react';
import { Tab, GameType } from '../types.ts';

interface PlinkoGameProps {
  balance: number;
  onUpdateBalance: (a: number) => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  onSound: (k: any) => void;
  adminOverride: number | null;
  onClearOverride: () => void;
  userBets: any[];
}

const PlinkoGame: React.FC<PlinkoGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab, onSound, adminOverride, onClearOverride, userBets }) => {
  const [bet, setBet] = useState(10);
  const [isDropping, setIsDropping] = useState(false);
  const [result, setResult] = useState<number | null>(null);

  const multipliers = [50, 20, 10, 5, 2, 0.5, 0.2, 0.5, 2, 5, 10, 20, 50];

  const handleDrop = () => {
    if (!hasAccess || isDropping || balance < bet) return;
    onSound('bet');
    onUpdateBalance(-bet);
    setIsDropping(true);
    setResult(null);

    let finalBucket = adminOverride !== null ? adminOverride : Math.floor(Math.random() * multipliers.length);
    if (adminOverride !== null) onClearOverride();

    setTimeout(() => {
      const win = bet * multipliers[finalBucket];
      onUpdateBalance(win);
      setResult(multipliers[finalBucket]);
      setIsDropping(false);
      onSound(win > bet ? 'win' : 'loss');
    }, 1500);
  };

  const myGameBets = userBets.filter(b => b.game === GameType.PLINKO).slice(0, 5);

  return (
    <div className="flex flex-col h-full bg-[#11131a] overflow-y-auto no-scrollbar pb-24">
      <div className="p-4 space-y-6">
        <div className="h-96 bg-[#0a0c10] rounded-[2.5rem] relative overflow-hidden border border-white/10 shadow-2xl flex flex-col items-center p-4">
          <div className="flex-1 w-full flex flex-col items-center justify-center gap-4 relative">
             <div className={`w-6 h-6 bg-pink-500 rounded-full shadow-[0_0_15px_rgba(236,72,153,0.5)] ${isDropping ? 'animate-bounce' : ''}`}></div>
             <div className="grid grid-cols-13 gap-1 w-full mt-auto">
                {multipliers.map((m, i) => (
                  <div key={i} className={`h-12 flex flex-col items-center justify-center rounded-lg text-[8px] font-black border border-white/5 ${m >= 10 ? 'bg-pink-600/20 text-pink-400' : 'bg-white/5 text-gray-500'}`}>
                     <span>{m}x</span>
                  </div>
                ))}
             </div>
          </div>
          {result !== null && (
            <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center z-20 animate-in zoom-in">
               <p className={`text-5xl font-black font-orbitron ${result >= 1 ? 'text-pink-500' : 'text-gray-500'}`}>{result}x</p>
               <button onClick={() => setResult(null)} className="mt-6 bg-white/10 px-8 py-2 rounded-full text-[10px] font-black uppercase">Drop Again</button>
            </div>
          )}
        </div>

        <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-4">
          {!hasAccess ? (
             <button onClick={() => setTab(Tab.WALLET)} className="w-full py-4 bg-pink-600 rounded-2xl font-black text-[10px] uppercase">Deposit ₹20 for Plinko</button>
          ) : (
             <>
                <div className="flex justify-between items-center bg-black/20 p-4 rounded-2xl">
                  <button onClick={() => setBet(Math.max(10, bet-10))} className="w-10 h-10 bg-white/5 rounded-xl font-black">-</button>
                  <div className="text-center"><p className="text-[8px] text-gray-600 font-black">BET</p><p className="text-lg font-black font-orbitron text-pink-500">🪙 {bet}</p></div>
                  <button onClick={() => setBet(bet+10)} className="w-10 h-10 bg-white/5 rounded-xl font-black">+</button>
                </div>
                <button onClick={handleDrop} disabled={isDropping} className="w-full py-5 rounded-3xl font-black text-lg uppercase bg-pink-600">Drop Ball</button>
             </>
          )}
        </div>
      </div>

      <div className="p-4 space-y-3">
         <h3 className="text-xs font-black font-orbitron text-gray-600 uppercase tracking-widest px-2">Plinko Ledger</h3>
         <div className="bg-[#1e2330] rounded-2xl overflow-hidden border border-white/5">
            {myGameBets.map(b => (
              <div key={b.id} className="p-4 border-b border-white/5 flex justify-between items-center text-[10px] font-black">
                 <div><p className="text-gray-400">{b.id}</p><p className="text-[8px] text-gray-600 uppercase">{new Date(b.timestamp).toLocaleTimeString()}</p></div>
                 <div className="text-right">
                    <p className={b.status === 'Win' ? 'text-green-500' : 'text-red-500'}>{b.status === 'Win' ? `+${b.payout}` : 'LOSS'}</p>
                 </div>
              </div>
            ))}
         </div>
      </div>
      <style>{`.grid-cols-13 { grid-template-columns: repeat(13, minmax(0, 1fr)); }`}</style>
    </div>
  );
};

