  onUpdateBalance: (a: number) => void;
  hasAccess: boolean;
  setTab: (t: Tab) => void;
  onSound: (k: any) => void;
  adminOverride: 'Player' | 'Banker' | 'Tie' | null;
  onClearOverride: () => void;
  userBets: any[];
}

const BaccaratGame: React.FC<BaccaratGameProps> = ({ balance, onUpdateBalance, hasAccess, setTab, onSound, adminOverride, onClearOverride, userBets }) => {
  const [bet, setBet] = useState(10);
  const [isPlaying, setIsPlaying] = useState(false);
  const [result, setResult] = useState<{ p: number, b: number, winner: string } | null>(null);
  const [myBet, setMyBet] = useState<{ side: string, amount: number } | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const periodDuration = 30000;
      const cycleTime = now % periodDuration;
      const bettingTime = 20000;

      if (cycleTime < bettingTime) {
        setIsPlaying(false);
        setTimeLeft(Math.ceil((bettingTime - cycleTime) / 1000));
        if (cycleTime < 1000) { setResult(null); setMyBet(null); }
      } else {
        if (!isPlaying) {
          let p = Math.floor(Math.random() * 9) + 1;
          let b = Math.floor(Math.random() * 9) + 1;
          if (adminOverride === 'Player') { p = 9; b = 1; onClearOverride(); }
          else if (adminOverride === 'Banker') { p = 1; b = 9; onClearOverride(); }
          else if (adminOverride === 'Tie') { p = 5; b = 5; onClearOverride(); }

          const winner = p > b ? 'Player' : b > p ? 'Banker' : 'Tie';
          setResult({ p, b, winner });

          if (myBet && myBet.side === winner) {
            const mult = winner === 'Tie' ? 9 : 2;
            onUpdateBalance(myBet.amount * mult);
            onSound('win');
          } else if (myBet) { onSound('loss'); }
        }
        setIsPlaying(true);
        setTimeLeft(Math.ceil((periodDuration - cycleTime) / 1000));
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [isPlaying, myBet, adminOverride]);

  const placeBet = (side: string) => {
    if (!hasAccess || isPlaying || myBet || balance < bet) return;
    onSound('bet');
    onUpdateBalance(-bet);
    setMyBet({ side, amount: bet });
  };

  const myGameBets = userBets.filter(b => b.game === GameType.BACCARAT).slice(0, 5);

  return (
    <div className="flex flex-col h-full bg-[#11131a] overflow-y-auto no-scrollbar pb-24">
      <div className="p-4 space-y-6">
        <div className="h-64 bg-gradient-to-b from-blue-900 to-black rounded-[2.5rem] relative overflow-hidden shadow-2xl flex flex-col items-center justify-center border border-white/10">
          <div className="flex justify-around w-full px-8">
             <div className="text-center space-y-2">
                <div className={`w-20 h-28 bg-white rounded-xl flex items-center justify-center text-3xl font-black text-blue-600 border-2 border-blue-400 ${result ? 'animate-in zoom-in' : 'opacity-20'}`}>{result ? result.p : '?'}</div>
                <p className="text-[10px] font-black text-blue-400 uppercase">Player</p>
             </div>
             <div className="text-center pt-8">
                <p className="text-2xl font-black text-white/20 font-orbitron">VS</p>
                {!result && <p className="text-xs font-black text-blue-500 animate-pulse mt-2">{timeLeft}s</p>}
             </div>
             <div className="text-center space-y-2">
                <div className={`w-20 h-28 bg-white rounded-xl flex items-center justify-center text-3xl font-black text-red-600 border-2 border-red-400 ${result ? 'animate-in zoom-in' : 'opacity-20'}`}>{result ? result.b : '?'}</div>
                <p className="text-[10px] font-black text-red-400 uppercase">Banker</p>
             </div>
          </div>
          {result && (
            <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-10 animate-in fade-in">
               <p className="text-4xl font-black font-orbitron text-yellow-500 uppercase italic shadow-xl">{result.winner} Wins!</p>
            </div>
          )}
        </div>

        <div className="bg-[#1e2330] p-6 rounded-[2.5rem] border border-white/5 space-y-6">
          {!hasAccess ? (
             <button onClick={() => setTab(Tab.WALLET)} className="w-full py-4 bg-blue-600 rounded-2xl font-black text-[10px] uppercase">Deposit ₹20 for Baccarat</button>
          ) : (
             <>
                <div className="grid grid-cols-3 gap-2">
                  <button onClick={() => placeBet('Player')} className={`py-4 rounded-xl font-black text-[10px] uppercase border transition-all ${myBet?.side === 'Player' ? 'bg-blue-600 border-white shadow-lg' : 'bg-blue-600/10 border-blue-500/20 text-blue-500'}`}>Player (2x)</button>
                  <button onClick={() => placeBet('Tie')} className={`py-4 rounded-xl font-black text-[10px] uppercase border transition-all ${myBet?.side === 'Tie' ? 'bg-gray-600 border-white shadow-lg' : 'bg-white/5 border-white/10 text-gray-500'}`}>Tie (9x)</button>
                  <button onClick={() => placeBet('Banker')} className={`py-4 rounded-xl font-black text-[10px] uppercase border transition-all ${myBet?.side === 'Banker' ? 'bg-red-600 border-white shadow-lg' : 'bg-red-600/10 border-red-500/20 text-red-500'}`}>Banker (2x)</button>
                </div>
                <div className="flex justify-between items-center bg-black/20 p-4 rounded-2xl">
                  <button onClick={() => setBet(Math.max(10, bet-10))} className="w-10 h-10 bg-white/5 rounded-xl font-black">-</button>
                  <div className="text-center"><p className="text-[8px] text-gray-600 font-black">STAKE</p><p className="text-lg font-black font-orbitron">🪙 {bet}</p></div>
                  <button onClick={() => setBet(bet+10)} className="w-10 h-10 bg-white/5 rounded-xl font-black">+</button>
                </div>
             </>
          )}
        </div>
      </div>

      <div className="p-4 space-y-3">
         <h3 className="text-xs font-black font-orbitron text-gray-600 uppercase tracking-widest px-2">Table Ledger</h3>
         <div className="bg-[#1e2330] rounded-2xl overflow-hidden border border-white/5">
            {myGameBets.map(b => (
              <div key={b.id} className="p-4 border-b border-white/5 flex justify-between items-center text-[10px] font-black">
                 <div><p className="text-gray-400">{b.id}</p><p className="text-[8px] text-gray-600 uppercase">{new Date(b.timestamp).toLocaleTimeString()}</p></div>
                 <div className="text-right">
                    <p className={b.status === 'Win' ? 'text-green-500' : 'text-red-500'}>{b.status} ({b.payout} INR)</p>
                 </div>
              </div>
            ))}
         </div>
      </div>
    </div>
  );
};

