           <div className="space-y-2">
              <p className="text-[9px] font-black text-gray-500 uppercase">Vortex (Idx 0-8)</p>
              <input type="number" placeholder="Target Idx" className="w-full bg-black/40 border border-white/5 rounded-xl p-3 text-xs" onBlur={(e) => updateSimpleControl('vortex', parseInt(e.target.value))} />
