              <p className="text-[9px] font-black text-gray-500 uppercase">Wheel (Idx 0-7)</p>
              <input type="number" placeholder="Target Idx" className="w-full bg-black/40 border border-white/5 rounded-xl p-3 text-xs" onBlur={(e) => updateSimpleControl('wheel', parseInt(e.target.value))} />
